// 病句 코스 9 — tools/make_bingju.py 가 tools/bingju/c09.json 에서 만든다. 직접 고치지 않는다.
(window.BJ=window.BJ||{})[9]=[[{"o":["孔子周游列国十四年，虽屡遭冷遇，却始终没有放弃推行德治的政治理想。","经过两千多年的口耳相传与反复注解，让《论语》中的许多语句成为了家喻户晓的格言。","敦煌莫高窟的壁画色彩斑斓、技艺精湛，被誉为“墙壁上的博物馆”。","宋代理学家朱熹将《大学》《中庸》《论语》《孟子》合编为“四书”，对后世科举影响深远。"],"a":1,"type":"주어 결여","why":"“经过…，让…” 때문에 문장에 주어가 없다. “让”을 빼야 “《论语》中的许多语句”가 주어가 된다.","fix":"经过两千多年的口耳相传与反复注解，《论语》中的许多语句成为了家喻户晓的格言。","words":[["周游列国","zhōu yóu liè guó","여러 나라를 돌아다니다"],["屡遭","lǚzāo","여러 번 당하다"],["冷遇","lěngyù","푸대접"],["家喻户晓","jiā yù hù xiǎo","집집마다 다 알다"],["斑斓","bānlán","알록달록 화려하다"],["精湛","jīngzhàn","(솜씨가) 뛰어나다"],["理学家","lǐxuéjiā","성리학자"],["科举","kējǔ","과거 시험"]],"tr":["공자는 14년 동안 여러 나라를 돌아다니며 번번이 푸대접을 받았지만, 덕으로 다스리겠다는 정치적 이상을 끝내 버리지 않았다.","2천여 년 동안 입에서 입으로 전해지고 거듭 주석이 달리면서 《논어》의 많은 구절이 누구나 아는 격언이 되었다.","둔황 막고굴의 벽화는 색채가 화려하고 기법이 뛰어나 '벽 위의 박물관'으로 불린다.","송나라 성리학자 주희는 《대학》《중용》《논어》《맹자》를 묶어 '사서'로 만들었고, 이는 후대 과거 시험에 큰 영향을 끼쳤다."],"ow":[[["周游列国","zhōu yóu liè guó","여러 나라를 돌아다니다"],["屡遭","lǚzāo","여러 번 당하다"],["冷遇","lěngyù","푸대접"]],[["家喻户晓","jiā yù hù xiǎo","집집마다 다 알다"],["口耳相传","kǒu ěr xiāng chuán","입에서 입으로 전하다"],["注解","zhùjiě","주석"]],[["斑斓","bānlán","알록달록 화려하다"],["精湛","jīngzhàn","(솜씨가) 뛰어나다"]],[["理学家","lǐxuéjiā","성리학자"],["科举","kējǔ","과거 시험"]]]},{"o":["黄河流经黄土高原时携带大量泥沙，下游河床逐年抬高，形成了举世闻名的“地上河”。","庄子在《逍遥游》中借鲲鹏展翅九万里的意象，抒发了超脱世俗、追求精神自由的情怀。","研究表明，适度的午睡不仅能缓解疲劳，还有助于提升下午的注意力和记忆力。","随着移动支付在城乡的迅速普及，使许多老年人也逐渐告别了随身携带现金的习惯。"],"a":3,"type":"주어 결여","why":"“随着…，使…” 때문에 주어가 없다. “使”를 빼야 “许多老年人”이 주어가 된다.","fix":"随着移动支付在城乡的迅速普及，许多老年人也逐渐告别了随身携带现金的习惯。","words":[["携带","xiédài","지니다, 싣고 가다"],["举世闻名","jǔ shì wén míng","온 세상에 이름나다"],["鲲鹏","kūnpéng","곤붕(전설의 큰 물고기와 큰 새)"],["意象","yìxiàng","심상, 이미지"],["抒发","shūfā","(감정을) 드러내다"],["超脱","chāotuō","벗어나다, 초탈하다"],["情怀","qínghuái","마음, 정서"],["普及","pǔjí","널리 퍼지다"]],"tr":["황허강은 황토고원을 지나며 많은 진흙과 모래를 싣고 가 하류의 강바닥이 해마다 높아졌고, 그 결과 세계적으로 유명한 '땅 위의 강'이 생겼다.","장자는 《소요유》에서 곤붕이 날개를 펴고 9만 리를 나는 모습을 빌려, 세속을 벗어나 정신의 자유를 추구하는 마음을 드러냈다.","연구에 따르면 적당한 낮잠은 피로를 풀어 줄 뿐 아니라 오후의 집중력과 기억력을 높이는 데도 도움이 된다.","모바일 결제가 도시와 농촌에 빠르게 퍼지면서 많은 노인도 현금을 들고 다니던 습관에서 점점 벗어났다."],"ow":[[["携带","xiédài","지니다, 싣고 가다"],["举世闻名","jǔ shì wén míng","온 세상에 이름나다"]],[["鲲鹏","kūnpéng","곤붕(전설의 큰 물고기와 큰 새)"],["意象","yìxiàng","심상, 이미지"],["抒发","shūfā","(감정을) 드러내다"],["超脱","chāotuō","벗어나다, 초탈하다"],["情怀","qínghuái","마음, 정서"]],[["缓解","huǎnjiě","완화하다"],["疲劳","píláo","피로"]],[["携带","xiédài","지니다, 싣고 가다"],["普及","pǔjí","널리 퍼지다"]]]},{"o":["在老子“上善若水”思想的深刻影响下，令后世不少文人把谦逊柔和视为立身处世的美德。","南宋数学家秦九韶在《数书九章》中提出的“大衍求一术”，比西方同类方法早了五百多年。","珊瑚礁虽然仅占海洋面积的极小部分，却孕育了约四分之一的海洋生物物种。","面对日新月异的市场变化，这家老字号企业没有故步自封，而是主动寻求转型。"],"a":0,"type":"주어 결여","why":"“在…影响下，令…” 때문에 주어가 없다. “令”을 빼야 “后世不少文人”이 주어가 된다.","fix":"在老子“上善若水”思想的深刻影响下，后世不少文人把谦逊柔和视为立身处世的美德。","words":[["上善若水","shàng shàn ruò shuǐ","가장 좋은 것은 물과 같다"],["谦逊","qiānxùn","겸손하다"],["立身处世","lì shēn chǔ shì","세상을 살아가다"],["秦九韶","Qín Jiǔsháo","진구소(남송 수학자)"],["大衍求一术","dàyǎn qiúyī shù","대연구일술(연립 합동식 풀이법)"],["孕育","yùnyù","품어 기르다"],["日新月异","rì xīn yuè yì","나날이 새로워지다"],["故步自封","gù bù zì fēng","제자리에 머물며 나아가지 않다"]],"tr":["'가장 좋은 것은 물과 같다'는 노자 사상의 깊은 영향으로, 후대의 많은 문인은 겸손하고 부드러운 태도를 세상을 살아가는 미덕으로 여겼다.","남송 수학자 진구소가 《수서구장》에서 내놓은 '대연구일술'은 서양의 같은 방법보다 500여 년 앞섰다.","산호초는 바다 면적의 아주 작은 부분만 차지하지만 바다 생물 종의 약 4분의 1을 품어 기른다.","나날이 바뀌는 시장 변화 앞에서 이 오래된 기업은 제자리에 머물지 않고 스스로 변신을 꾀했다."],"ow":[[["上善若水","shàng shàn ruò shuǐ","가장 좋은 것은 물과 같다"],["谦逊","qiānxùn","겸손하다"],["立身处世","lì shēn chǔ shì","세상을 살아가다"]],[["秦九韶","Qín Jiǔsháo","진구소(남송 수학자)"],["大衍求一术","dàyǎn qiúyī shù","대연구일술(연립 합동식 풀이법)"]],[["孕育","yùnyù","품어 기르다"],["珊瑚礁","shānhújiāo","산호초"],["物种","wùzhǒng","생물 종"]],[["日新月异","rì xīn yuè yì","나날이 새로워지다"],["故步自封","gù bù zì fēng","제자리에 머물며 나아가지 않다"]]]},{"o":["战国时期，商鞅在秦国推行改革，使秦国逐渐成为七国中实力最强的国家。","陆羽撰写的《茶经》系统总结了唐代以前的种茶、制茶经验，被誉为世界上第一部茶学专著。","由于长期过度放牧和盲目开垦，使这一地区的草场严重退化，沙尘天气日益频繁。","人们常用“韦编三绝”来形容读书勤奋刻苦，这个成语源于孔子晚年反复研读《周易》的故事。"],"a":2,"type":"주어 결여","why":"“由于…，使…” 때문에 주어가 없다. “使”를 빼야 “这一地区的草场”이 주어가 된다.","fix":"由于长期过度放牧和盲目开垦，这一地区的草场严重退化，沙尘天气日益频繁。","words":[["商鞅","Shāng Yāng","상앙(전국 시대 개혁가)"],["撰写","zhuànxiě","(글을) 쓰다"],["专著","zhuānzhù","전문 저서"],["放牧","fàngmù","방목하다"],["开垦","kāikěn","개간하다"],["退化","tuìhuà","퇴화하다, 황폐해지다"],["韦编三绝","wéi biān sān jué","책끈이 세 번 끊어지도록 읽다"],["研读","yándú","깊이 읽다"]],"tr":["전국 시대에 상앙이 진나라에서 개혁을 펼쳐, 진나라는 점차 일곱 나라 가운데 가장 강한 나라가 되었다.","육우가 쓴 《다경》은 당나라 이전의 차 재배와 차 만드는 경험을 체계적으로 정리해 세계 최초의 차 전문서로 꼽힌다.","오랫동안 지나치게 방목하고 무분별하게 개간한 탓에 이 지역의 초원은 심하게 황폐해졌고 황사가 날로 잦아졌다.","사람들은 흔히 '위편삼절'로 부지런히 공부하는 모습을 나타내는데, 이 성어는 공자가 말년에 《주역》을 되풀이해 읽은 이야기에서 나왔다."],"ow":[[["商鞅","Shāng Yāng","상앙(전국 시대 개혁가)"],["推行","tuīxíng","널리 시행하다"],["实力","shílì","실력, 국력"]],[["撰写","zhuànxiě","(글을) 쓰다"],["专著","zhuānzhù","전문 저서"]],[["放牧","fàngmù","방목하다"],["开垦","kāikěn","개간하다"],["退化","tuìhuà","퇴화하다, 황폐해지다"]],[["韦编三绝","wéi biān sān jué","책끈이 세 번 끊어지도록 읽다"],["研读","yándú","깊이 읽다"]]]},{"o":["墨子主张“兼爱”“非攻”，反对一切以掠夺为目的的战争，在当时可谓独树一帜。","算盘以珠代筹，运算简便迅速，在电子计算器普及之前，一直是商铺账房里不可或缺的计算工具。","针对近年来网络谣言传播速度快、波及范围广、危害程度深的问题，有关部门的一系列整治措施。","这部纪录片以细腻的镜头记录了非遗传承人的日常，让观众感受到了匠心的分量。"],"a":2,"type":"술어 결여","why":"“针对…的问题” 뒤에 “有关部门的一系列整治措施”라는 명사구만 있고, 무엇을 했는지 말하는 동사가 없다.","fix":"针对近年来网络谣言传播速度快、波及范围广、危害程度深的问题，有关部门出台了一系列整治措施。","words":[["兼爱","jiān'ài","차별 없이 두루 사랑함"],["非攻","fēigōng","침략 전쟁 반대"],["掠夺","lüèduó","약탈하다"],["独树一帜","dú shù yí zhì","독자적인 길을 열다"],["算盘","suànpan","주판"],["不可或缺","bù kě huò quē","없어서는 안 되다"],["谣言","yáoyán","헛소문"],["整治","zhěngzhì","바로잡아 다스리다"]],"tr":["묵자는 '겸애'와 '비공'을 내세우며 약탈을 목적으로 하는 모든 전쟁에 반대했으니, 당시로서는 독보적인 주장이었다.","주판은 산가지 대신 알을 써서 셈이 간편하고 빨라, 전자계산기가 널리 쓰이기 전까지 상점 장부방에 없어서는 안 될 계산 도구였다.","최근 인터넷 헛소문이 빨리 퍼지고 범위가 넓으며 피해가 크다는 문제에 대해 관련 부서가 일련의 정비 대책을 내놓았다.","이 다큐멘터리는 섬세한 화면으로 무형문화재 전승자의 일상을 담아, 관객이 장인 정신의 무게를 느끼게 했다."],"ow":[[["兼爱","jiān'ài","차별 없이 두루 사랑함"],["非攻","fēigōng","침략 전쟁 반대"],["掠夺","lüèduó","약탈하다"],["独树一帜","dú shù yí zhì","독자적인 길을 열다"]],[["算盘","suànpan","주판"],["不可或缺","bù kě huò quē","없어서는 안 되다"]],[["谣言","yáoyán","헛소문"],["整治","zhěngzhì","바로잡아 다스리다"]],[["细腻","xìnì","섬세하다"],["传承人","chuánchéngrén","전승자"],["匠心","jiàngxīn","장인 정신"]]]},{"o":["近年来，许多高校对于如何把传统典籍中的智慧与现代管理理念有机结合起来。","魏晋时期的刘徽创立“割圆术”，用不断倍增圆内接正多边形边数的方法来逼近圆的面积。","研究人员发现，蜜蜂能通过复杂的“舞蹈”向同伴传递蜜源的方向和距离。","“塞翁失马，焉知非福”告诉我们，祸与福在一定条件下是可以相互转化的。"],"a":0,"type":"술어 결여","why":"“许多高校对于如何…结合起来” 뒤에 고등학교들이 무엇을 했는지(연구했다 등) 말하는 동사가 없다.","fix":"近年来，许多高校对于如何把传统典籍中的智慧与现代管理理念有机结合起来进行了深入探讨。","words":[["典籍","diǎnjí","고전 서적"],["有机","yǒujī","유기적으로"],["刘徽","Liú Huī","유휘(위진 수학자)"],["割圆术","gēyuánshù","할원술(원 넓이 근사법)"],["逼近","bījìn","근접하다"],["蜜源","mìyuán","꿀을 딸 수 있는 곳"],["塞翁失马","sài wēng shī mǎ","새옹지마"],["焉知非福","yān zhī fēi fú","복이 아닌 줄 어찌 알랴"]],"tr":["최근 많은 대학이 전통 고전의 지혜를 현대 경영 이념과 어떻게 유기적으로 결합할지 깊이 논의했다.","위진 시대의 유휘는 '할원술'을 만들어, 원에 내접하는 정다각형의 변을 계속 두 배로 늘려 가며 원의 넓이에 다가갔다.","연구자들은 꿀벌이 복잡한 '춤'으로 동료에게 꿀이 있는 곳의 방향과 거리를 알린다는 사실을 발견했다.","'변방 노인이 말을 잃었으나 그것이 복이 아닌 줄 어찌 알겠는가'라는 말은 화와 복이 조건에 따라 서로 바뀔 수 있음을 알려 준다."],"ow":[[["典籍","diǎnjí","고전 서적"],["有机","yǒujī","유기적으로"]],[["刘徽","Liú Huī","유휘(위진 수학자)"],["割圆术","gēyuánshù","할원술(원 넓이 근사법)"],["逼近","bījìn","근접하다"]],[["蜜源","mìyuán","꿀을 딸 수 있는 곳"],["蜜蜂","mìfēng","꿀벌"],["传递","chuándì","전달하다"]],[["塞翁失马","sài wēng shī mǎ","새옹지마"],["焉知非福","yān zhī fēi fú","복이 아닌 줄 어찌 알랴"]]]},{"o":["元代天文学家郭守敬主持编订的《授时历》，测定一年为三百六十五点二四二五日。","考古出土的秦代铜权上大多刻有统一度量衡的诏书，是研究秦朝法制的珍贵实物。","古人用十天干与十二地支依次相配，组成六十个序号循环纪年，这就是“六十甲子”的由来。","为了使濒临失传的古琴艺术后继有人，这位年逾古稀的老琴师多年来坚持免费向青少年。"],"a":3,"type":"술어 결여","why":"“坚持免费向青少年” 뒤에 무엇을 하는지(가르치다)가 빠져 문장이 끝나지 않았다.","fix":"为了使濒临失传的古琴艺术后继有人，这位年逾古稀的老琴师多年来坚持免费向青少年传授琴艺。","words":[["郭守敬","Guō Shǒujìng","곽수경(원 천문학자)"],["授时历","Shòushí Lì","수시력(원나라 역법)"],["诏书","zhàoshū","조서"],["天干","tiāngān","천간"],["濒临","bīnlín","(위기에) 처하다"],["失传","shīchuán","전해지지 않게 되다"],["后继有人","hòu jì yǒu rén","뒤를 이을 사람이 있다"],["年逾古稀","nián yú gǔ xī","일흔이 넘다"]],"tr":["원나라 천문학자 곽수경이 주도해 만든 《수시력》은 1년을 365.2425일로 정했다.","출토된 진나라 구리 저울추에는 대부분 도량형 통일 조서가 새겨져 있어, 진나라 법제를 연구하는 귀한 실물이 된다.","옛사람들은 10천간과 12지지를 차례로 짝지어 60개의 순번으로 해를 돌아가며 셌는데, 이것이 '육십갑자'의 유래다.","사라질 위기에 놓인 고금 예술의 맥을 잇기 위해 일흔이 넘은 이 노악사는 여러 해 동안 청소년들에게 무료로 가르쳐 왔다."],"ow":[[["郭守敬","Guō Shǒujìng","곽수경(원 천문학자)"],["授时历","Shòushí Lì","수시력(원나라 역법)"]],[["诏书","zhàoshū","조서"],["铜权","tóngquán","구리 저울추"],["度量衡","dùliànghéng","도량형"]],[["天干","tiāngān","천간"],["地支","dìzhī","지지"],["六十甲子","liùshí jiǎzǐ","육십갑자"]],[["濒临","bīnlín","(위기에) 처하다"],["失传","shīchuán","전해지지 않게 되다"],["后继有人","hòu jì yǒu rén","뒤를 이을 사람이 있다"],["年逾古稀","nián yú gǔ xī","일흔이 넘다"]]]},{"o":["韩非子以“守株待兔”的寓言讽刺那些墨守成规、不知变通的统治者。","这项补贴政策的实施，极大地调动了偏远山区农民种植中药材的。","南北朝数学家祖暅提出“幂势既同，则积不容异”，比意大利学者卡瓦列里早了一千多年。","心理学研究发现，人在面对过多选择时，反而更容易陷入犹豫不决的状态。"],"a":1,"type":"목적어 결여","why":"“调动了…种植中药材的” 뒤에 꾸밈을 받는 목적어(积极性)가 없다.","fix":"这项补贴政策的实施，极大地调动了偏远山区农民种植中药材的积极性。","words":[["补贴","bǔtiē","보조금"],["调动","diàodòng","불러일으키다"],["中药材","zhōngyàocái","한약재"],["守株待兔","shǒu zhū dài tù","그루터기를 지켜 토끼를 기다리다"],["墨守成规","mò shǒu chéng guī","낡은 규칙을 고집하다"],["变通","biàntōng","융통성 있게 바꾸다"],["祖暅","Zǔ Gèng","조긍(남북조 수학자)"],["犹豫不决","yóu yù bù jué","망설이며 결정하지 못하다"]],"tr":["한비자는 '수주대토' 우화로, 낡은 규칙만 고집하고 융통성이 없는 통치자들을 비꼬았다.","이 보조금 정책이 시행되면서 외딴 산간 지역 농민들의 한약재 재배 의욕이 크게 높아졌다.","남북조 시대 수학자 조긍은 '단면이 같으면 부피도 다를 수 없다'는 원리를 내놓았는데, 이는 이탈리아 학자 카발리에리보다 천여 년 앞섰다.","심리학 연구에 따르면 사람은 선택지가 너무 많으면 오히려 망설이며 결정하지 못하는 상태에 빠지기 쉽다."],"ow":[[["守株待兔","shǒu zhū dài tù","그루터기를 지켜 토끼를 기다리다"],["墨守成规","mò shǒu chéng guī","낡은 규칙을 고집하다"],["变通","biàntōng","융통성 있게 바꾸다"]],[["补贴","bǔtiē","보조금"],["调动","diàodòng","불러일으키다"],["中药材","zhōngyàocái","한약재"]],[["祖暅","Zǔ Gèng","조긍(남북조 수학자)"],["幂","mì","단면(넓이)"],["卡瓦列里","Kǎwǎlièlǐ","카발리에리"]],[["犹豫不决","yóu yù bù jué","망설이며 결정하지 못하다"],["心理学","xīnlǐxué","심리학"],["陷入","xiànrù","빠지다"]]]},{"o":["我国古代长期以十六两为一斤，“半斤八两”这一说法便由此而来，比喻彼此不相上下。","晏子出使楚国时，面对楚王的刻意刁难，从容应对，维护了齐国的尊严。","屈原在《离骚》中表达了他忧国忧民、宁死也不愿与世俗同流合污的。","由于气候干燥、降水稀少，吐鲁番盆地成为了我国著名的葡萄和哈密瓜产区。"],"a":2,"type":"중심어 결여","why":"“表达了…同流合污的” 뒤에 꾸밈을 받는 명사(情怀 등)가 없다.","fix":"屈原在《离骚》中表达了他忧国忧民、宁死也不愿与世俗同流合污的高洁情怀。","words":[["半斤八两","bàn jīn bā liǎng","피차일반"],["不相上下","bù xiāng shàng xià","우열을 가리기 어렵다"],["晏子","Yànzǐ","안자(춘추 시대 제나라 재상)"],["刁难","diāonàn","일부러 곤란하게 하다"],["从容","cóngróng","침착하다"],["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["同流合污","tóng liú hé wū","나쁜 무리와 어울리다"],["吐鲁番","Tǔlǔfān","투루판"]],"tr":["옛날 중국은 오랫동안 열여섯 냥을 한 근으로 삼았기에 '반 근이나 여덟 냥이나'라는 말이 생겼고, 서로 우열을 가리기 어렵다는 뜻으로 쓴다.","안자는 초나라에 사신으로 갔을 때 초왕이 일부러 곤란하게 만들자 침착하게 대응해 제나라의 체면을 지켰다.","굴원은 《이소》에서 나라와 백성을 걱정하며 죽을지언정 세속과 어울려 더럽혀지지 않겠다는 고결한 마음을 드러냈다.","기후가 건조하고 비가 적어 투루판 분지는 중국에서 이름난 포도와 하미과 산지가 되었다."],"ow":[[["半斤八两","bàn jīn bā liǎng","피차일반"],["不相上下","bù xiāng shàng xià","우열을 가리기 어렵다"]],[["晏子","Yànzǐ","안자(춘추 시대 제나라 재상)"],["刁难","diāonàn","일부러 곤란하게 하다"],["从容","cóngróng","침착하다"]],[["忧国忧民","yōu guó yōu mín","나라와 백성을 걱정하다"],["同流合污","tóng liú hé wū","나쁜 무리와 어울리다"]],[["吐鲁番","Tǔlǔfān","투루판"],["盆地","péndì","분지"],["哈密瓜","hāmìguā","하미과(멜론)"]]]},{"o":["这次考古发掘出土的大批青铜器和竹简，为研究战国时期楚国的社会风貌提供了。","荀子主张人性本恶，认为只有依靠后天的教化和礼法的约束，人才能弃恶从善。","成书于西汉的《周髀算经》记载了“勾三股四弦五”的特例，是我国最早的天文数学著作之一。","这位企业家常说，管理者最难得的品质不是精明，而是知人善任、虚怀若谷。"],"a":0,"type":"목적어 결여","why":"“提供了” 뒤에 무엇을 제공했는지 목적어(资料)가 없다.","fix":"这次考古发掘出土的大批青铜器和竹简，为研究战国时期楚国的社会风貌提供了珍贵的实物资料。","words":[["发掘","fājué","발굴하다"],["竹简","zhújiǎn","죽간"],["风貌","fēngmào","모습, 면모"],["教化","jiàohuà","가르쳐 이끌다"],["弃恶从善","qì è cóng shàn","악을 버리고 선을 따르다"],["周髀算经","Zhōubì Suànjīng","주비산경(고대 천문 수학서)"],["知人善任","zhī rén shàn rèn","사람을 알아보고 잘 쓰다"],["虚怀若谷","xū huái ruò gǔ","마음이 골짜기처럼 넓고 겸허하다"]],"tr":["이번 발굴에서 나온 많은 청동기와 죽간은 전국 시대 초나라의 사회 모습을 연구하는 데 귀중한 자료를 제공했다.","순자는 사람의 본성이 악하다고 보고, 후천적인 교화와 예법의 단속이 있어야만 사람이 악을 버리고 선을 따를 수 있다고 했다.","서한 때 책으로 엮인 《주비산경》에는 '구고현이 3·4·5'인 특수한 경우가 실려 있으며, 중국에서 가장 오래된 천문 수학서 가운데 하나다.","이 기업가는 관리자에게 가장 귀한 자질은 영리함이 아니라 사람을 알아보고 잘 쓰며 겸허하게 받아들이는 마음이라고 늘 말한다."],"ow":[[["发掘","fājué","발굴하다"],["竹简","zhújiǎn","죽간"],["风貌","fēngmào","모습, 면모"]],[["教化","jiàohuà","가르쳐 이끌다"],["弃恶从善","qì è cóng shàn","악을 버리고 선을 따르다"]],[["周髀算经","Zhōubì Suànjīng","주비산경(고대 천문 수학서)"],["勾三股四弦五","gōu sān gǔ sì xián wǔ","직각삼각형 3·4·5"],["著作","zhùzuò","저서"]],[["知人善任","zhī rén shàn rèn","사람을 알아보고 잘 쓰다"],["虚怀若谷","xū huái ruò gǔ","마음이 골짜기처럼 넓고 겸허하다"]]]}],[{"o":["长城并非一次建成，而是历经春秋战国至明代多次修筑而成，绵延万余里。","这家拥有百年历史的药铺，至今仍坚持按古法炮制药材，从不偷工减料。","相传孔子一生收徒讲学，门下弟子大约三千人左右，其中精通六艺者有七十二人。","鲸虽然生活在海洋中，却是用肺呼吸的哺乳动物，需要定时浮出水面换气。"],"a":2,"type":"어림수 중복","why":"“大约”와 “左右”가 둘 다 ‘쯤’이라는 뜻이라 겹친다. 하나만 남겨야 한다.","fix":"相传孔子一生收徒讲学，门下弟子约三千人，其中精通六艺者有七十二人。","words":[["修筑","xiūzhù","쌓다, 건설하다"],["绵延","miányán","길게 이어지다"],["药铺","yàopù","약방"],["炮制","páozhì","(한약재를) 법제하다"],["偷工减料","tōu gōng jiǎn liào","일을 대충 하고 재료를 줄이다"],["讲学","jiǎngxué","학문을 가르치다"],["六艺","liùyì","육예(예·악·사·어·서·수)"],["哺乳动物","bǔrǔ dòngwù","포유동물"]],"tr":["만리장성은 한 번에 지어진 것이 아니라 춘추전국 시대부터 명나라까지 여러 번 쌓아 만든 것으로, 만여 리에 걸쳐 이어진다.","100년 역사의 이 약방은 지금도 옛 방식대로 약재를 법제하며 한 번도 일을 대충 하거나 재료를 아낀 적이 없다.","전하는 말에 따르면 공자는 평생 제자를 받아 가르쳤는데 제자가 3천 명쯤 되었고, 그중 육예에 통달한 사람이 72명이었다.","고래는 바다에 살지만 폐로 숨 쉬는 포유동물이라 때맞춰 물 위로 올라와 숨을 바꿔 쉬어야 한다."],"ow":[[["修筑","xiūzhù","쌓다, 건설하다"],["绵延","miányán","길게 이어지다"]],[["药铺","yàopù","약방"],["炮制","páozhì","(한약재를) 법제하다"],["偷工减料","tōu gōng jiǎn liào","일을 대충 하고 재료를 줄이다"]],[["讲学","jiǎngxué","학문을 가르치다"],["六艺","liùyì","육예(예·악·사·어·서·수)"]],[["哺乳动物","bǔrǔ dòngwù","포유동물"],["鲸","jīng","고래"],["定时","dìngshí","때맞춰"]]]},{"o":["这座始建于北宋的石拱桥历经近千年左右的风雨侵蚀，桥身依然坚固如初。","道家主张“无为而治”，并不是让统治者无所作为，而是要顺应自然、不妄加干预。","一项追踪调查显示，长期睡眠不足的青少年更容易出现情绪波动和注意力下降。","宋代的瓷器以造型简洁、釉色温润著称，汝、官、哥、钧、定五大名窑各具特色。"],"a":0,"type":"어림수 중복","why":"“近”(가까이)과 “左右”(쯤)가 둘 다 어림수 표현이라 겹친다.","fix":"这座始建于北宋的石拱桥历经近千年的风雨侵蚀，桥身依然坚固如初。","words":[["石拱桥","shígǒngqiáo","돌 아치교"],["侵蚀","qīnshí","침식하다"],["无为而治","wú wéi ér zhì","억지로 하지 않고 다스리다"],["妄加","wàngjiā","함부로 더하다"],["干预","gānyù","간섭하다"],["釉色","yòusè","유약 색"],["温润","wēnrùn","부드럽고 윤기 있다"],["名窑","míngyáo","이름난 가마"]],"tr":["북송 때 처음 지어진 이 돌 아치교는 천 년 가까이 비바람에 깎였지만 다리는 여전히 처음처럼 튼튼하다.","도가의 '무위이치'는 통치자에게 아무것도 하지 말라는 것이 아니라 자연을 따르고 함부로 간섭하지 말라는 뜻이다.","한 추적 조사에 따르면 오랫동안 잠이 부족한 청소년은 감정 기복과 집중력 저하가 더 쉽게 나타난다.","송나라 도자기는 간결한 모양과 부드럽고 윤기 나는 유약 색으로 이름났고, 여·관·가·균·정 다섯 명요가 저마다 특색이 있다."],"ow":[[["石拱桥","shígǒngqiáo","돌 아치교"],["侵蚀","qīnshí","침식하다"]],[["无为而治","wú wéi ér zhì","억지로 하지 않고 다스리다"],["妄加","wàngjiā","함부로 더하다"],["干预","gānyù","간섭하다"]],[["追踪","zhuīzōng","추적하다"],["波动","bōdòng","기복, 변동"]],[["釉色","yòusè","유약 색"],["温润","wēnrùn","부드럽고 윤기 있다"],["名窑","míngyáo","이름난 가마"]]]},{"o":["惠施与庄子在濠水桥上关于“鱼之乐”的辩论，体现了两人截然不同的思维方式。","由于地处季风区，这一带夏季高温多雨，冬季寒冷干燥，四季分明。","只有深入了解消费者的真实需求，企业才能在激烈的竞争中立于不败之地。","司马迁忍辱负重，耗尽毕生一辈子的心血，终于完成了被誉为“史家之绝唱”的《史记》。"],"a":3,"type":"뜻 중복","why":"“毕生”이 이미 ‘한평생’이라는 뜻이라 “一辈子”와 겹친다.","fix":"司马迁忍辱负重，耗尽毕生心血，终于完成了被誉为“史家之绝唱”的《史记》。","words":[["惠施","Huì Shī","혜시(전국 시대 사상가)"],["截然不同","jié rán bù tóng","전혀 다르다"],["季风","jìfēng","계절풍"],["立于不败之地","lì yú bú bài zhī dì","지지 않을 위치에 서다"],["忍辱负重","rěn rǔ fù zhòng","치욕을 참고 중임을 지다"],["毕生","bìshēng","한평생"],["绝唱","juéchàng","최고의 걸작"]],"tr":["혜시와 장자가 호수의 다리 위에서 '물고기의 즐거움'을 두고 벌인 논쟁은 두 사람의 전혀 다른 사고방식을 보여 준다.","계절풍 지역에 있어서 이 일대는 여름에 덥고 비가 많으며 겨울에 춥고 건조해 사계절이 뚜렷하다.","소비자의 진짜 요구를 깊이 이해해야만 기업이 치열한 경쟁에서 지지 않는 자리에 설 수 있다.","사마천은 치욕을 참고 무거운 짐을 지며 평생의 정성을 다 쏟아, 마침내 '역사가의 마지막 절창'이라 불리는 《사기》를 완성했다."],"ow":[[["惠施","Huì Shī","혜시(전국 시대 사상가)"],["截然不同","jié rán bù tóng","전혀 다르다"]],[["季风","jìfēng","계절풍"],["地处","dìchǔ","~에 위치하다"],["四季分明","sìjì fēnmíng","사계절이 뚜렷하다"]],[["立于不败之地","lì yú bú bài zhī dì","지지 않을 위치에 서다"],["消费者","xiāofèizhě","소비자"],["激烈","jīliè","치열하다"]],[["忍辱负重","rěn rǔ fù zhòng","치욕을 참고 중임을 지다"],["毕生","bìshēng","한평생"],["绝唱","juéchàng","최고의 걸작"]]]},{"o":["敦煌藏经洞的发现，为研究中古时期的宗教、语言与社会生活提供了大量第一手资料。","战国时期赵武灵王推行“胡服骑射”，其目的是为了增强军队的机动性和作战能力。","那位老中医告诫年轻人，养生贵在持之以恒，切不可急于求成。","竹子看似柔弱，却能在狂风中弯而不折，因而常被文人用来象征坚贞的气节。"],"a":1,"type":"뜻 중복","why":"“目的是”와 “为了”가 둘 다 목적을 나타내서 겹친다.","fix":"战国时期赵武灵王推行“胡服骑射”，其目的是增强军队的机动性和作战能力。","words":[["藏经洞","cángjīngdòng","장경동(둔황 경전 동굴)"],["胡服骑射","hú fú qí shè","호복을 입고 말 타며 활쏘기"],["机动性","jīdòngxìng","기동성"],["告诫","gàojiè","타이르다"],["持之以恒","chí zhī yǐ héng","꾸준히 지속하다"],["急于求成","jí yú qiú chéng","성급하게 성과를 바라다"],["坚贞","jiānzhēn","굳고 곧다"],["气节","qìjié","절개"]],"tr":["둔황 장경동의 발견은 중세의 종교, 언어, 사회생활을 연구하는 데 많은 1차 자료를 제공했다.","전국 시대 조나라 무령왕이 '호복기사'를 시행한 목적은 군대의 기동성과 전투력을 높이는 것이었다.","그 노한의사는 젊은이들에게 몸 관리는 꾸준함이 가장 중요하니 절대 서둘러 성과를 바라지 말라고 타일렀다.","대나무는 약해 보여도 거센 바람에 휘어질 뿐 꺾이지 않아, 문인들이 굳고 곧은 절개를 상징하는 데 자주 썼다."],"ow":[[["藏经洞","cángjīngdòng","장경동(둔황 경전 동굴)"],["敦煌","Dūnhuáng","둔황"],["第一手资料","dìyīshǒu zīliào","1차 자료"]],[["胡服骑射","hú fú qí shè","호복을 입고 말 타며 활쏘기"],["机动性","jīdòngxìng","기동성"]],[["告诫","gàojiè","타이르다"],["持之以恒","chí zhī yǐ héng","꾸준히 지속하다"],["急于求成","jí yú qiú chéng","성급하게 성과를 바라다"]],[["坚贞","jiānzhēn","굳고 곧다"],["气节","qìjié","절개"]]]},{"o":["“三人行，必有我师焉”启示我们，要善于发现他人的长处，虚心向别人学习。","萤火虫发出的光几乎不产生热量，因此被科学家称为“冷光”。","“螳螂捕蝉，黄雀在后”提醒人们，不能只顾眼前利益而忽视身后潜伏的危险。","许多古代名画色彩黯淡、绢面破损，主要原因是长期保存不当、受潮发霉的缘故。"],"a":3,"type":"뜻 중복","why":"“原因是”와 “…的缘故”가 둘 다 ‘이유’를 말해 겹친다.","fix":"许多古代名画色彩黯淡、绢面破损，主要原因是长期保存不当、受潮发霉。","words":[["虚心","xūxīn","겸허하다"],["萤火虫","yínghuǒchóng","반딧불이"],["螳螂捕蝉","táng láng bǔ chán","사마귀가 매미를 잡다"],["潜伏","qiánfú","숨어 있다"],["黯淡","àndàn","어둡고 칙칙하다"],["绢","juàn","비단(그림 바탕)"],["受潮","shòucháo","습기가 차다"],["发霉","fāméi","곰팡이가 피다"]],"tr":["'세 사람이 길을 가면 반드시 내 스승이 있다'는 말은 남의 장점을 잘 찾아내고 겸허하게 배우라고 일깨운다.","반딧불이가 내는 빛은 열을 거의 만들지 않아 과학자들은 이를 '차가운 빛'이라고 부른다.","'사마귀가 매미를 잡는데 꾀꼬리가 뒤에 있다'는 말은 눈앞의 이익만 보다가 뒤에 숨은 위험을 놓치지 말라고 일깨운다.","많은 옛 명화가 색이 바래고 비단 바탕이 해진 주된 원인은 오랫동안 잘못 보관해 습기가 차고 곰팡이가 핀 데 있다."],"ow":[[["虚心","xūxīn","겸허하다"],["三人行，必有我师焉","sān rén xíng, bì yǒu wǒ shī yān","세 사람이 가면 반드시 스승이 있다"],["启示","qǐshì","일깨우다"]],[["萤火虫","yínghuǒchóng","반딧불이"],["热量","rèliàng","열량"],["冷光","lěngguāng","냉광"]],[["螳螂捕蝉","táng láng bǔ chán","사마귀가 매미를 잡다"],["潜伏","qiánfú","숨어 있다"]],[["黯淡","àndàn","어둡고 칙칙하다"],["绢","juàn","비단(그림 바탕)"],["受潮","shòucháo","습기가 차다"],["发霉","fāméi","곰팡이가 피다"]]]},{"o":["随着城市化进程的加快，热岛效应日益变得越来越显著，夏季城区气温往往高出郊区好几度。","曾子“吾日三省吾身”的说法，强调了时常自我反省对于修身的重要意义。","这位导演善于从平凡小事中挖掘深刻的主题，作品往往于无声处见真情。","汉字从甲骨文、金文发展到篆书、隶书，字形经历了由繁到简的演变过程。"],"a":0,"type":"뜻 중복","why":"“日益”가 이미 ‘날이 갈수록’이라는 뜻이라 “越来越”와 겹친다.","fix":"随着城市化进程的加快，热岛效应日益显著，夏季城区气温往往高出郊区好几度。","words":[["热岛效应","rèdǎo xiàoyìng","열섬 현상"],["日益","rìyì","날로"],["显著","xiǎnzhù","뚜렷하다"],["吾日三省吾身","wú rì sān xǐng wú shēn","나는 하루에 세 번 나를 돌아본다"],["反省","fǎnxǐng","반성하다"],["挖掘","wājué","파내다, 발굴하다"],["篆书","zhuànshū","전서"],["隶书","lìshū","예서"]],"tr":["도시화가 빨라지면서 열섬 현상이 날로 뚜렷해져, 여름철 도심 기온이 교외보다 몇 도씩 높은 경우가 많다.","증자의 '나는 하루에 세 번 나 자신을 돌아본다'는 말은 늘 스스로 반성하는 것이 수양에 얼마나 중요한지 강조한다.","이 감독은 평범한 일상에서 깊은 주제를 잘 끌어내, 작품마다 소리 없는 곳에서 진심이 드러난다.","한자는 갑골문과 금문에서 전서와 예서로 발전하며, 글자 모양이 복잡한 것에서 간단한 것으로 바뀌어 왔다."],"ow":[[["热岛效应","rèdǎo xiàoyìng","열섬 현상"],["日益","rìyì","날로"],["显著","xiǎnzhù","뚜렷하다"]],[["吾日三省吾身","wú rì sān xǐng wú shēn","나는 하루에 세 번 나를 돌아본다"],["反省","fǎnxǐng","반성하다"]],[["挖掘","wājué","파내다, 발굴하다"],["平凡","píngfán","평범하다"],["于无声处","yú wú shēng chù","소리 없는 곳에서"]],[["篆书","zhuànshū","전서"],["隶书","lìshū","예서"]]]},{"o":["唐代僧人一行组织人员实地测量，在世界上首次推算出了子午线一度的长度。","新研制的这款传感器灵敏度极高，能在几秒钟内检测出空气中的微量有害气体。","凡是所有到过泰山的游客，都会被日出时云海翻腾、霞光万道的壮丽景象所震撼。","东晋画家顾恺之主张“以形写神”，认为人物画的关键在于传达人物的内在精神。"],"a":2,"type":"기타 군더더기","why":"“凡是”와 “所有”가 둘 다 ‘모든’이라는 뜻이라 하나가 군더더기다.","fix":"凡是到过泰山的游客，都会被日出时云海翻腾、霞光万道的壮丽景象所震撼。","words":[["一行","Yīxíng","일행(당나라 승려 천문학자)"],["子午线","zǐwǔxiàn","자오선"],["推算","tuīsuàn","추산하다"],["传感器","chuángǎnqì","센서"],["灵敏度","língmǐndù","감도"],["翻腾","fānténg","뒤끓다, 굽이치다"],["震撼","zhènhàn","뒤흔들다, 감동시키다"],["以形写神","yǐ xíng xiě shén","형체로 정신을 그리다"]],"tr":["명나라 의약학자 이시진은 27년에 걸쳐 본초학을 집대성한 《본초강목》을 엮어 냈다.","새로 개발한 이 센서는 감도가 매우 높아 몇 초 만에 공기 속 미량의 유해 가스를 찾아낼 수 있다.","태산에 올라 본 관광객이라면 누구나 해돋이 때 구름바다가 굽이치고 노을빛이 사방으로 뻗는 장관에 압도된다.","동진의 화가 고개지는 '형체로 정신을 그린다'고 주장하며, 인물화의 핵심은 인물의 내면을 전하는 데 있다고 보았다."],"ow":[[["一行","Yīxíng","일행(당나라 승려 천문학자)"],["子午线","zǐwǔxiàn","자오선"],["推算","tuīsuàn","추산하다"]],[["传感器","chuángǎnqì","센서"],["灵敏度","língmǐndù","감도"]],[["翻腾","fānténg","뒤끓다, 굽이치다"],["震撼","zhènhàn","뒤흔들다, 감동시키다"]],[["以形写神","yǐ xíng xiě shén","형체로 정신을 그리다"],["顾恺之","Gù Kǎizhī","고개지(동진 화가)"],["东晋","Dōng Jìn","동진"]]]},{"o":["骆驼的驼峰里储存的是脂肪而不是水，在食物匮乏时可以转化为能量。","诸葛亮在《出师表》中再三反复叮嘱后主刘禅要亲贤臣、远小人，言辞恳切，感人至深。","这家民营企业坚持把一部分利润投入研发，十年间获得了上百项发明专利。","“纸上得来终觉浅，绝知此事要躬行”说明，从书本上得来的知识必须经过亲身实践才能真正领会。"],"a":1,"type":"기타 군더더기","why":"“再三”과 “反复”가 둘 다 ‘거듭’이라는 뜻이라 겹친다.","fix":"诸葛亮在《出师表》中再三叮嘱后主刘禅要亲贤臣、远小人，言辞恳切，感人至深。","words":[["驼峰","tuófēng","낙타 혹"],["匮乏","kuìfá","모자라다"],["研发","yánfā","연구 개발"],["专利","zhuānlì","특허"],["出师表","Chūshī Biǎo","출사표"],["叮嘱","dīngzhǔ","신신당부하다"],["恳切","kěnqiè","간절하다"],["躬行","gōngxíng","몸소 행하다"]],"tr":["낙타 혹에 저장된 것은 물이 아니라 지방으로, 먹이가 모자랄 때 에너지로 바뀐다.","제갈량은 《출사표》에서 후주 유선에게 어진 신하를 가까이하고 소인을 멀리하라고 거듭 당부했는데, 말이 간절해 깊은 감동을 준다.","이 민간 기업은 이익의 일부를 꾸준히 연구 개발에 쏟아 10년 사이 발명 특허를 백 건 넘게 얻었다.","'종이 위에서 얻은 것은 끝내 얕으니 제대로 알려면 몸소 해 봐야 한다'는 말은 책에서 얻은 지식은 직접 실천해 봐야 참으로 깨칠 수 있음을 보여 준다."],"ow":[[["驼峰","tuófēng","낙타 혹"],["匮乏","kuìfá","모자라다"]],[["出师表","Chūshī Biǎo","출사표"],["叮嘱","dīngzhǔ","신신당부하다"],["恳切","kěnqiè","간절하다"]],[["研发","yánfā","연구 개발"],["专利","zhuānlì","특허"]],[["躬行","gōngxíng","몸소 행하다"],["终觉浅","zhōng jué qiǎn","끝내 얕게 느껴지다"],["领会","lǐnghuì","깨닫다"]]]},{"o":["孔子提出“君子和而不同”，主张在保持和谐的同时尊重彼此之间的差异。","每年深秋，成千上万只斑头雁从青藏高原飞越喜马拉雅山，到印度一带越冬。","这位作家的散文语言质朴、意蕴深厚，读来如饮清茶，回味无穷。","为了防止这批明代古籍继续受损，图书馆邀请专家对其加以进行修复和数字化保存。"],"a":3,"type":"기타 군더더기","why":"“加以”와 “进行”이 둘 다 뒤 동사를 이끄는 같은 역할이라 하나가 군더더기다.","fix":"为了防止这批明代古籍继续受损，图书馆邀请专家对其进行修复和数字化保存。","words":[["古籍","gǔjí","옛 서적"],["受损","shòusǔn","손상되다"],["和而不同","hé ér bù tóng","화합하되 같아지지 않는다"],["斑头雁","bāntóuyàn","줄기러기"],["越冬","yuèdōng","겨울을 나다"],["质朴","zhìpǔ","소박하다"],["意蕴","yìyùn","속뜻, 함축"],["回味无穷","huí wèi wú qióng","여운이 끝없다"]],"tr":["공자는 '군자는 화합하되 같아지지 않는다'고 하며, 조화를 지키면서도 서로의 차이를 존중하자고 했다.","해마다 늦가을이면 수많은 줄기러기가 칭짱고원에서 히말라야산맥을 넘어 인도 일대로 가서 겨울을 난다.","이 작가의 수필은 말이 소박하고 속뜻이 깊어, 읽고 나면 맑은 차를 마신 듯 여운이 오래 남는다.","이 명나라 고서들이 더 손상되지 않도록 도서관은 전문가를 불러 복원하고 디지털로 보존하게 했다."],"ow":[[["和而不同","hé ér bù tóng","화합하되 같아지지 않는다"],["君子","jūnzǐ","군자"],["和谐","héxié","조화"]],[["斑头雁","bāntóuyàn","줄기러기"],["越冬","yuèdōng","겨울을 나다"]],[["质朴","zhìpǔ","소박하다"],["意蕴","yìyùn","속뜻, 함축"],["回味无穷","huí wèi wú qióng","여운이 끝없다"]],[["古籍","gǔjí","옛 서적"],["受损","shòusǔn","손상되다"]]]},{"o":["吸烟不仅危害自身健康，而且产生的二手烟还会对周围的人造成伤害。","这位学者关于对魏晋玄学与道家养生思想之间渊源的研究，在学界引起了广泛关注。","杭州西湖的苏堤是北宋文学家苏轼任杭州知州时主持疏浚西湖后修筑的。","尽管“愚公移山”只是一则寓言，但它所传达的坚韧不拔的精神至今仍激励着人们。"],"a":1,"type":"기타 군더더기","why":"개사 “关于”와 “对”를 겹쳐 썼다. 하나만 써야 한다.","fix":"这位学者关于魏晋玄学与道家养生思想之间渊源的研究，在学界引起了广泛关注。","words":[["玄学","xuánxué","현학(위진 시대 철학)"],["渊源","yuānyuán","근원, 내력"],["知州","zhīzhōu","지주(주의 장관)"],["疏浚","shūjùn","준설하다"],["愚公移山","yú gōng yí shān","우공이 산을 옮기다"],["寓言","yùyán","우화"],["坚韧不拔","jiān rèn bù bá","굳세어 흔들리지 않다"]],"tr":["담배는 피우는 사람의 건강을 해칠 뿐 아니라, 거기서 나오는 간접흡연 연기가 주변 사람에게도 해를 끼친다.","위진 현학과 도가 양생 사상 사이의 근원에 관한 이 학자의 연구는 학계에서 큰 주목을 받았다.","항저우 시후의 쑤디는 북송 문학가 소식이 항저우 지주로 있을 때 시후 준설을 맡은 뒤 쌓은 둑이다.","'우공이산'은 우화일 뿐이지만, 거기 담긴 굳세고 흔들리지 않는 정신은 지금도 사람들을 북돋운다."],"ow":[[["危害","wēihài","해치다"],["二手烟","èrshǒuyān","간접흡연 연기"]],[["玄学","xuánxué","현학(위진 시대 철학)"],["渊源","yuānyuán","근원, 내력"]],[["知州","zhīzhōu","지주(주의 장관)"],["疏浚","shūjùn","준설하다"]],[["愚公移山","yú gōng yí shān","우공이 산을 옮기다"],["寓言","yùyán","우화"],["坚韧不拔","jiān rèn bù bá","굳세어 흔들리지 않다"]]]}],[{"o":["公民在依法履行选举权利的同时，也应当自觉承担起维护社会公共秩序的责任。","老子所说的“知足不辱，知止不殆”，劝诫人们懂得适可而止，不要贪得无厌。","太湖石以“瘦、皱、漏、透”为美，是我国古典园林中常见的观赏石。","这项调查结果表明，城市居民对公共文化服务的满意度近年来稳步上升。"],"a":0,"type":"동사–목적어","why":"“权利”는 “履行”(의무를 다하다)과 어울리지 않는다. 권리는 “行使”(행사하다)한다.","fix":"公民在依法行使选举权利的同时，也应当自觉承担起维护社会公共秩序的责任。","words":[["履行","lǚxíng","(의무를) 이행하다"],["知足不辱","zhī zú bù rǔ","만족할 줄 알면 욕되지 않다"],["劝诫","quànjiè","타일러 경계하다"],["适可而止","shì kě ér zhǐ","적당한 때 멈추다"],["贪得无厌","tān dé wú yàn","욕심이 끝이 없다"],["太湖石","tàihúshí","태호석"],["稳步","wěnbù","꾸준히"]],"tr":["시민은 법에 따라 선거권을 행사하는 동시에 사회 공공질서를 지킬 책임도 스스로 져야 한다.","노자의 '만족할 줄 알면 욕되지 않고 멈출 줄 알면 위태롭지 않다'는 말은 적당할 때 멈추고 끝없이 욕심내지 말라고 타이른다.","태호석은 '여위고, 주름지고, 구멍 나고, 뚫린' 모양을 아름답게 여기며, 중국 고전 정원에서 흔히 보는 감상용 돌이다.","이 조사 결과에 따르면 도시 주민의 공공 문화 서비스 만족도가 최근 몇 년 동안 꾸준히 올라갔다."],"ow":[[["履行","lǚxíng","(의무를) 이행하다"],["依法","yīfǎ","법에 따라"],["秩序","zhìxù","질서"]],[["知足不辱","zhī zú bù rǔ","만족할 줄 알면 욕되지 않다"],["劝诫","quànjiè","타일러 경계하다"],["适可而止","shì kě ér zhǐ","적당한 때 멈추다"],["贪得无厌","tān dé wú yàn","욕심이 끝이 없다"]],[["太湖石","tàihúshí","태호석"],["古典园林","gǔdiǎn yuánlín","고전 정원"],["观赏石","guānshǎngshí","감상용 돌"]],[["稳步","wěnbù","꾸준히"],["满意度","mǎnyìdù","만족도"],["表明","biǎomíng","보여 주다"]]]},{"o":["庄子认为“吾生也有涯，而知也无涯”，提醒人们以有限的生命追逐无限的知识是危险的。","这种深海鱼类长期生活在漆黑的环境中，视力几乎完全丧失，却进化出了极其灵敏的侧线系统。","为了纪念顾炎武诞辰四百周年，当地博物馆召开了一场明清之际学人手稿展览。","不少网友认为，这部改编自同名小说的电视剧既忠实于原著，又有所创新。"],"a":2,"type":"동사–목적어","why":"“召开”은 회의에 쓰는 말이라 “展览”(전시회)과 어울리지 않는다. 전시회는 “举办”한다.","fix":"为了纪念顾炎武诞辰四百周年，当地博物馆举办了一场明清之际学人手稿展览。","words":[["无涯","wúyá","끝이 없다"],["追逐","zhuīzhú","뒤쫓다"],["漆黑","qīhēi","칠흑같이 어둡다"],["侧线","cèxiàn","옆줄(물고기 감각 기관)"],["顾炎武","Gù Yánwǔ","고염무(명말청초 학자)"],["诞辰","dànchén","탄신"],["手稿","shǒugǎo","친필 원고"],["原著","yuánzhù","원작"]],"tr":["장자는 '삶에는 끝이 있으나 앎에는 끝이 없다'며, 한정된 삶으로 끝없는 앎을 쫓는 것은 위험하다고 일깨웠다.","이 심해어는 오랫동안 칠흑 같은 곳에서 살아 시력을 거의 잃었지만, 대신 아주 예민한 옆줄 감각을 발달시켰다.","고염무 탄신 400주년을 기념해 현지 박물관이 명말청초 학자들의 친필 원고 전시회를 열었다.","많은 네티즌은 같은 이름의 소설을 각색한 이 드라마가 원작에 충실하면서도 새로운 시도가 있다고 본다."],"ow":[[["无涯","wúyá","끝이 없다"],["追逐","zhuīzhú","뒤쫓다"]],[["漆黑","qīhēi","칠흑같이 어둡다"],["侧线","cèxiàn","옆줄(물고기 감각 기관)"]],[["顾炎武","Gù Yánwǔ","고염무(명말청초 학자)"],["诞辰","dànchén","탄신"],["手稿","shǒugǎo","친필 원고"]],[["原著","yuánzhù","원작"],["改编","gǎibiān","각색하다"],["忠实","zhōngshí","충실하다"]]]},{"o":["植物通过光合作用将二氧化碳和水转化为有机物，同时释放出氧气。","范仲淹“先天下之忧而忧，后天下之乐而乐”的名句，充分培养了古代士大夫以天下为己任的胸怀。","这家公司凭借精准的市场定位和过硬的产品质量，在短短几年内迅速打开了海外市场。","南宋数学家杨辉在著作中记录了二项式系数的排列规律，后人称之为“杨辉三角”。"],"a":1,"type":"동사–목적어","why":"명구가 사대부의 마음을 “培养”(기르다)했다는 말은 어울리지 않는다. 그 마음을 “体现”(보여 주다)했다고 해야 한다.","fix":"范仲淹“先天下之忧而忧，后天下之乐而乐”的名句，充分体现了古代士大夫以天下为己任的胸怀。","words":[["光合作用","guānghé zuòyòng","광합성"],["范仲淹","Fàn Zhòngyān","범중엄(북송 정치가)"],["士大夫","shìdàfū","사대부"],["胸怀","xiōnghuái","포부, 마음"],["精准","jīngzhǔn","정확하다"],["过硬","guòyìng","믿을 만큼 뛰어나다"],["杨辉","Yáng Huī","양휘(남송 수학자)"],["二项式","èrxiàngshì","이항식"]],"tr":["식물은 광합성으로 이산화탄소와 물을 유기물로 바꾸고, 동시에 산소를 내보낸다.","범중엄의 '천하의 근심은 남보다 먼저 근심하고, 천하의 즐거움은 남보다 나중에 즐긴다'는 명구는 천하를 제 일로 여긴 옛 사대부의 마음을 잘 보여 준다.","이 회사는 정확한 시장 위치 설정과 믿음직한 제품 품질로 불과 몇 년 만에 해외 시장을 열었다.","남송 수학자 양휘는 저서에 이항식 계수가 늘어서는 규칙을 기록했고, 후대 사람들은 이를 '양휘 삼각형'이라 불렀다."],"ow":[[["光合作用","guānghé zuòyòng","광합성"],["二氧化碳","èryǎnghuàtàn","이산화탄소"],["释放","shìfàng","내보내다"]],[["范仲淹","Fàn Zhòngyān","범중엄(북송 정치가)"],["士大夫","shìdàfū","사대부"],["胸怀","xiōnghuái","포부, 마음"]],[["精准","jīngzhǔn","정확하다"],["过硬","guòyìng","믿을 만큼 뛰어나다"]],[["杨辉","Yáng Huī","양휘(남송 수학자)"],["二项式","èrxiàngshì","이항식"]]]},{"o":["王阳明提出“知行合一”，强调认识事物与付诸实践是不可分割的两个方面。","这件出土于扬州的新莽铜卡尺，结构原理与现代游标卡尺颇为相似，堪称精巧。","“汗牛充栋”原指藏书极多，搬运时累得牛出汗，存放时堆满屋子。","经过多年的悉心培育，这片荒漠上的梭梭林的面积已经郁郁葱葱，成为阻挡风沙的绿色屏障。"],"a":3,"type":"주어–술어","why":"“郁郁葱葱”(울창하다)는 숲을 말하는데 주어가 “面积”(넓이)라 맞지 않는다.","fix":"经过多年的悉心培育，这片荒漠上的梭梭林已经郁郁葱葱，成为阻挡风沙的绿色屏障。","words":[["知行合一","zhī xíng hé yī","앎과 행함은 하나다"],["付诸","fùzhū","~에 옮기다"],["游标卡尺","yóubiāo kǎchǐ","버니어 캘리퍼스"],["堪称","kānchēng","~라 할 만하다"],["汗牛充栋","hàn niú chōng dòng","책이 아주 많다"],["悉心","xīxīn","온 마음을 다하다"],["郁郁葱葱","yù yù cōng cōng","울창하다"],["屏障","píngzhàng","가림막, 방벽"]],"tr":["왕양명은 '지행합일'을 내세워, 사물을 아는 것과 실천에 옮기는 것은 떼어 놓을 수 없는 두 면이라고 강조했다.","양저우에서 출토된 이 신나라 구리 캘리퍼스는 구조와 원리가 현대의 버니어 캘리퍼스와 꽤 비슷해 정교하다고 할 만하다.","'한우충동'은 원래 책이 아주 많아 옮길 때는 소가 땀을 흘리고 쌓아 두면 집이 가득 찬다는 뜻이다.","여러 해 정성껏 가꾼 끝에 이 사막의 사사나무 숲은 울창해져 모래바람을 막는 푸른 방벽이 되었다."],"ow":[[["知行合一","zhī xíng hé yī","앎과 행함은 하나다"],["付诸","fùzhū","~에 옮기다"]],[["游标卡尺","yóubiāo kǎchǐ","버니어 캘리퍼스"],["堪称","kānchēng","~라 할 만하다"]],[["汗牛充栋","hàn niú chōng dòng","책이 아주 많다"],["藏书","cángshū","장서"],["搬运","bānyùn","옮기다"]],[["悉心","xīxīn","온 마음을 다하다"],["郁郁葱葱","yù yù cōng cōng","울창하다"],["屏障","píngzhàng","가림막, 방벽"]]]},{"o":["《庄子》一书文笔汪洋恣肆，想象奇特瑰丽，其中许多寓言的寓意短小精悍，读来发人深省。","这项研究追踪了上千名志愿者长达二十年的饮食习惯，结论具有很高的参考价值。","由于缺乏天敌，这种外来植物在当地迅速蔓延，严重威胁着本地物种的生存。","齐桓公不计一箭之仇，听从鲍叔牙的举荐，任用管仲为相，终成春秋霸业。"],"a":0,"type":"주어–술어","why":"“短小精悍”(짧고 알차다)은 우화 자체를 말하는데 주어가 “寓意”(속뜻)라 맞지 않는다.","fix":"《庄子》一书文笔汪洋恣肆，想象奇特瑰丽，其中许多寓言短小精悍、寓意深刻，读来发人深省。","words":[["汪洋恣肆","wāng yáng zì sì","(글이) 거침없고 호방하다"],["瑰丽","guīlì","아름답고 화려하다"],["短小精悍","duǎn xiǎo jīng hàn","짧고 알차다"],["发人深省","fā rén shēn xǐng","깊이 생각하게 하다"],["天敌","tiāndí","천적"],["蔓延","mànyán","퍼지다"],["举荐","jǔjiàn","천거하다"],["霸业","bàyè","패업"]],"tr":["《장자》는 문장이 거침없고 상상이 기이하고 화려하며, 그 안의 많은 우화는 짧고 알차면서 속뜻이 깊어 읽으면 깊은 생각에 잠기게 한다.","이 연구는 천여 명의 지원자를 20년 동안 추적하며 식습관을 살펴, 결론의 참고 가치가 매우 높다.","천적이 없어서 이 외래 식물은 현지에서 빠르게 퍼져 토종 생물의 생존을 크게 위협하고 있다.","제환공은 화살 맞은 원한을 따지지 않고 포숙아의 천거를 받아들여 관중을 재상으로 삼았고, 마침내 춘추의 패업을 이루었다."],"ow":[[["汪洋恣肆","wāng yáng zì sì","(글이) 거침없고 호방하다"],["瑰丽","guīlì","아름답고 화려하다"],["短小精悍","duǎn xiǎo jīng hàn","짧고 알차다"],["发人深省","fā rén shēn xǐng","깊이 생각하게 하다"]],[["追踪","zhuīzōng","추적하다"],["志愿者","zhìyuànzhě","지원자"]],[["天敌","tiāndí","천적"],["蔓延","mànyán","퍼지다"]],[["举荐","jǔjiàn","천거하다"],["霸业","bàyè","패업"]]]},{"o":["“鸡兔同笼”是《孙子算经》中的一道趣题，至今仍常被用来训练学生的逻辑思维。","这位工程师花了三年时间，攻克了困扰行业多年的技术难题。","“程门立雪”这个成语出自宋代杨时拜访老师程颐的故事，常用来形容尊师重道。","被称为“亚圣”的孟子，是战国时期儒家学派最具代表性的思想之一。"],"a":3,"type":"주어–목적어","why":"“孟子是…思想之一”이 되어 사람(맹자)을 사상이라고 했다. “人物之一”라고 해야 한다.","fix":"被称为“亚圣”的孟子，是战国时期儒家学派最具代表性的人物之一。","words":[["鸡兔同笼","jī tù tóng lóng","닭과 토끼 셈 문제"],["孙子算经","Sūnzǐ Suànjīng","손자산경(고대 수학서)"],["攻克","gōngkè","극복하다, 해결하다"],["困扰","kùnrǎo","괴롭히다"],["程门立雪","Chéng mén lì xuě","정씨 문 앞에 눈 맞으며 서다(스승 공경)"],["尊师重道","zūn shī zhòng dào","스승을 받들고 도를 중히 여기다"],["亚圣","Yàshèng","아성(맹자의 존칭)"]],"tr":["산성비는 건물과 문화유산을 부식시키고, 흙을 산성화하며 호수의 물고기를 떼죽음에 이르게 한다.","'닭과 토끼가 한 우리에' 문제는 《손자산경》에 실린 재미있는 문제로, 지금도 학생들의 논리적 사고를 훈련하는 데 자주 쓰인다.","'정씨 문 앞에 서서 눈을 맞다'라는 성어는 송나라 양시가 스승 정이를 찾아간 이야기에서 나왔고, 스승을 공경하는 모습을 나타낼 때 쓴다.","'아성'으로 불리는 맹자는 전국 시대 유가 학파를 가장 잘 대표하는 인물 가운데 하나다."],"ow":[[["鸡兔同笼","jī tù tóng lóng","닭과 토끼 셈 문제"],["孙子算经","Sūnzǐ Suànjīng","손자산경(고대 수학서)"]],[["攻克","gōngkè","극복하다, 해결하다"],["困扰","kùnrǎo","괴롭히다"]],[["程门立雪","Chéng mén lì xuě","정씨 문 앞에 눈 맞으며 서다(스승 공경)"],["尊师重道","zūn shī zhòng dào","스승을 받들고 도를 중히 여기다"]],[["亚圣","Yàshèng","아성(맹자의 존칭)"],["孟子","Mèngzǐ","맹자"],["儒家","Rújiā","유가"]]]},{"o":["庄子妻子去世时，他非但不哭，反而敲着瓦盆唱歌，令前来吊唁的友人十分不解。","古代的浑仪由多个同心圆环组成，可以用来测定天体的位置和运行轨迹。","这次文物普查的主要目的，是摸清全省不可移动文物的分布状况和保存现状的一次大规模调查。","这家图书馆实行二十四小时开放，深夜里仍有不少读者在这里埋头苦读。"],"a":2,"type":"주어–목적어","why":"“目的是…调查”가 되어 목적을 조사라고 했다. 끝의 “的一次大规模调查”를 빼야 한다.","fix":"这次文物普查的主要目的，是摸清全省不可移动文物的分布状况和保存现状。","words":[["吊唁","diàoyàn","조문하다"],["浑仪","húnyí","혼의(천체 관측기)"],["天体","tiāntǐ","천체"],["轨迹","guǐjì","궤적"],["普查","pǔchá","전수 조사"],["摸清","mōqīng","정확히 파악하다"],["埋头苦读","mái tóu kǔ dú","몰두해 열심히 읽다"]],"tr":["장자는 아내가 죽었을 때 울기는커녕 질그릇을 두드리며 노래해, 조문하러 온 벗이 몹시 의아해했다.","옛 혼의는 여러 개의 동심 원고리로 이루어져 천체의 위치와 움직임을 재는 데 쓰였다.","이번 문화재 전수 조사의 주된 목적은 성 전체의 옮길 수 없는 문화재가 어디에 어떻게 남아 있는지 정확히 파악하는 것이다.","이 도서관은 24시간 문을 열어, 한밤중에도 여전히 많은 사람이 몰두해 책을 읽는다."],"ow":[[["吊唁","diàoyàn","조문하다"],["非但","fēidàn","~하기는커녕"],["瓦盆","wǎpén","질그릇 동이"]],[["浑仪","húnyí","혼의(천체 관측기)"],["天体","tiāntǐ","천체"],["轨迹","guǐjì","궤적"]],[["普查","pǔchá","전수 조사"],["摸清","mōqīng","정확히 파악하다"]],[["埋头苦读","mái tóu kǔ dú","몰두해 열심히 읽다"],["实行","shíxíng","실시하다"],["深夜","shēnyè","한밤중"]]]},{"o":["秦岭—淮河一线大致与一月零摄氏度等温线吻合，是我国南北方重要的地理分界线。","“兼听则明，偏信则暗”告诉我们，领导者能否广泛听取各方意见，是其作出正确决策的重要保证。","这位科学家淡泊名利，把全部奖金捐给了家乡的学校，用于资助贫困学生。","许多候鸟在迁徙途中依靠地磁场、太阳和星辰来辨别方向。"],"a":1,"type":"양면–한면","why":"앞은 “能否”(할 수 있는지 없는지) 두 면인데, 뒤 “重要保证”은 ‘할 수 있다’ 한 면에만 맞는다.","fix":"“兼听则明，偏信则暗”告诉我们，领导者广泛听取各方意见，是其作出正确决策的重要保证。","words":[["等温线","děngwēnxiàn","등온선"],["吻合","wěnhé","들어맞다"],["兼听则明","jiān tīng zé míng","두루 들으면 밝아진다"],["偏信则暗","piān xìn zé àn","한쪽만 믿으면 어두워진다"],["决策","juécè","결정"],["淡泊名利","dàn bó míng lì","명예와 이익에 담담하다"],["资助","zīzhù","재정 지원하다"],["迁徙","qiānxǐ","이동하다"]],"tr":["친링-화이허 선은 1월 0도 등온선과 대체로 들어맞아 중국 남북을 가르는 중요한 지리 경계선이다.","'두루 들으면 밝아지고 한쪽만 믿으면 어두워진다'는 말은 지도자가 여러 의견을 널리 듣는 것이 옳은 결정을 내리는 중요한 바탕임을 알려 준다.","이 과학자는 명예와 이익에 담담해 상금을 모두 고향 학교에 기부해 가난한 학생들을 돕는 데 쓰게 했다.","많은 철새는 이동하는 길에 지구 자기장, 태양, 별을 이용해 방향을 가린다."],"ow":[[["等温线","děngwēnxiàn","등온선"],["吻合","wěnhé","들어맞다"]],[["兼听则明","jiān tīng zé míng","두루 들으면 밝아진다"],["偏信则暗","piān xìn zé àn","한쪽만 믿으면 어두워진다"],["决策","juécè","결정"]],[["淡泊名利","dàn bó míng lì","명예와 이익에 담담하다"],["资助","zīzhù","재정 지원하다"]],[["迁徙","qiānxǐ","이동하다"],["候鸟","hòuniǎo","철새"],["地磁场","dìcíchǎng","지구 자기장"],["辨别","biànbié","가려내다"]]]},{"o":["古人早已认识到，地方官吏品行的优劣，直接决定着一方百姓生活水平的提高。","这种被称为“活化石”的银杏树，早在两亿多年前就已出现在地球上。","老子以“治大国若烹小鲜”为喻，告诫统治者施政不可朝令夕改、扰民生事。","近年来，越来越多的年轻人开始走进剧场，欣赏昆曲、京剧等传统戏曲。"],"a":0,"type":"양면–한면","why":"앞은 “优劣”(좋고 나쁨) 두 면인데, 뒤는 “提高”(높아짐) 한 면이라 맞지 않는다.","fix":"古人早已认识到，地方官吏品行的优劣，直接决定着一方百姓生活水平的高低。","words":[["官吏","guānlì","관리"],["品行","pǐnxíng","품행"],["优劣","yōuliè","좋고 나쁨"],["活化石","huóhuàshí","살아 있는 화석"],["银杏","yínxìng","은행나무"],["治大国若烹小鲜","zhì dà guó ruò pēng xiǎo xiān","큰 나라 다스리기는 작은 생선 굽듯 하라"],["朝令夕改","zhāo lìng xī gǎi","명령을 자주 바꾸다"],["昆曲","kūnqǔ","곤곡(전통극)"]],"tr":["옛사람들은 지방 관리의 품행이 좋고 나쁨이 그 지역 백성의 생활 수준을 곧바로 좌우한다는 것을 일찍이 알았다.","'살아 있는 화석'이라 불리는 은행나무는 이미 2억여 년 전에 지구에 나타났다.","노자는 '큰 나라를 다스리는 것은 작은 생선을 굽는 것과 같다'고 비유하며, 통치자에게 명령을 자주 바꾸거나 백성을 괴롭히지 말라고 타일렀다.","최근 점점 더 많은 젊은이가 극장을 찾아 곤곡, 경극 같은 전통극을 즐기기 시작했다."],"ow":[[["官吏","guānlì","관리"],["品行","pǐnxíng","품행"],["优劣","yōuliè","좋고 나쁨"]],[["活化石","huóhuàshí","살아 있는 화석"],["银杏","yínxìng","은행나무"]],[["治大国若烹小鲜","zhì dà guó ruò pēng xiǎo xiān","큰 나라 다스리기는 작은 생선 굽듯 하라"],["朝令夕改","zhāo lìng xī gǎi","명령을 자주 바꾸다"]],[["昆曲","kūnqǔ","곤곡(전통극)"],["剧场","jùchǎng","극장"],["戏曲","xìqǔ","전통극"]]]},{"o":["这条高速铁路穿越崇山峻岭，沿线修建了上百座隧道和桥梁。","海水中的盐分主要来自岩石风化后被河流带入大海的矿物质。","反复研读先秦诸子的经典著作，能够陶冶人的情操和明辨是非的能力。","他在书法上造诣颇深，尤其擅长草书，笔势奔放而不失法度。"],"a":2,"type":"목적어 일부 불일치","why":"“陶冶”는 “情操”와는 맞지만 “明辨是非的能力”와는 맞지 않는다. 능력은 “提高”해야 한다.","fix":"反复研读先秦诸子的经典著作，能够陶冶人的情操，提高人明辨是非的能力。","words":[["崇山峻岭","chóng shān jùn lǐng","높고 험한 산들"],["风化","fēnghuà","풍화하다"],["先秦","Xiān Qín","선진(진나라 이전)"],["诸子","zhūzǐ","제자(여러 사상가)"],["陶冶","táoyě","도야하다"],["情操","qíngcāo","정서, 품성"],["明辨是非","míng biàn shì fēi","옳고 그름을 가리다"],["造诣","zàoyì","조예"]],"tr":["이 고속철도는 높고 험한 산들을 지나며, 노선을 따라 백 개가 넘는 터널과 다리를 놓았다.","바닷물의 소금기는 주로 바위가 풍화된 뒤 강물에 실려 바다로 들어간 광물질에서 온다.","선진 제자의 고전을 되풀이해 깊이 읽으면 마음을 바르게 가꾸고 옳고 그름을 가리는 힘을 기를 수 있다.","그는 서예에 조예가 깊고 특히 초서에 뛰어나, 붓놀림이 거침없으면서도 법도를 잃지 않는다."],"ow":[[["崇山峻岭","chóng shān jùn lǐng","높고 험한 산들"],["隧道","suìdào","터널"],["沿线","yánxiàn","노선을 따라"]],[["风化","fēnghuà","풍화하다"],["盐分","yánfèn","염분"],["矿物质","kuàngwùzhì","광물질"]],[["先秦","Xiān Qín","선진(진나라 이전)"],["诸子","zhūzǐ","제자(여러 사상가)"],["陶冶","táoyě","도야하다"],["情操","qíngcāo","정서, 품성"],["明辨是非","míng biàn shì fēi","옳고 그름을 가리다"]],[["造诣","zàoyì","조예"],["草书","cǎoshū","초서"],["奔放","bēnfàng","거침없다"],["法度","fǎdù","법도"]]]}],[{"o":["孔子主张“因材施教”，针对弟子们不同的性格和资质给予不同的指点。","近年来，随着冰川加速消融，一些高山湖泊发生溃决的风险明显上升。","这家博物馆运用全息投影技术，让沉睡千年的文物仿佛“活”了过来。","由于年代久远、战乱频仍，后人把这部兵书的许多篇章没有完整地保存下来。"],"a":3,"type":"부정사 위치","why":"부정사 “没有”는 “把” 앞에 와야 한다. “把…没有…”는 순서가 틀렸다.","fix":"由于年代久远、战乱频仍，后人没有把这部兵书的许多篇章完整地保存下来。","words":[["因材施教","yīn cái shī jiào","자질에 맞게 가르치다"],["资质","zīzhì","타고난 자질"],["消融","xiāoróng","녹다"],["溃决","kuìjué","(둑 등이) 터지다"],["全息投影","quánxī tóuyǐng","홀로그램 투영"],["频仍","pínréng","잇따르다"],["兵书","bīngshū","병법서"]],"tr":["공자는 '자질에 맞게 가르친다'를 내세워, 제자들의 서로 다른 성격과 자질에 따라 다르게 이끌어 주었다.","최근 빙하가 빨리 녹으면서 일부 고산 호수가 터질 위험이 눈에 띄게 커졌다.","이 박물관은 홀로그램 기술을 써서 천 년 동안 잠들어 있던 문화재가 마치 '살아난' 듯 보이게 했다.","세월이 오래되고 전란이 잇따라, 후대 사람들은 이 병법서의 많은 편을 온전히 보존하지 못했다."],"ow":[[["因材施教","yīn cái shī jiào","자질에 맞게 가르치다"],["资质","zīzhì","타고난 자질"]],[["消融","xiāoróng","녹다"],["溃决","kuìjué","(둑 등이) 터지다"]],[["全息投影","quánxī tóuyǐng","홀로그램 투영"],["沉睡","chénshuì","깊이 잠들다"],["文物","wénwù","문화재"]],[["频仍","pínréng","잇따르다"],["兵书","bīngshū","병법서"]]]},{"o":["庄子用“庖丁解牛”的故事说明，做事只有顺应事物的规律，才能游刃有余。","这一考古发现将也许会彻底改写人们对长江流域早期文明起源的认识。","数学家华罗庚自学成才，在解析数论等领域取得了举世瞩目的成就。","专家提醒，长时间低头看手机容易导致颈椎劳损，应当适时活动一下颈部。"],"a":1,"type":"부사 위치","why":"추측을 나타내는 부사 “也许”는 “将” 앞에 와야 한다. “将也许会”는 순서가 틀렸다.","fix":"这一考古发现也许将会彻底改写人们对长江流域早期文明起源的认识。","words":[["庖丁解牛","páo dīng jiě niú","백정이 소를 잡듯 능숙하다"],["游刃有余","yóu rèn yǒu yú","여유 있게 해내다"],["改写","gǎixiě","고쳐 쓰다"],["华罗庚","Huà Luógēng","화뤄겅(현대 수학자)"],["举世瞩目","jǔ shì zhǔ mù","온 세상이 주목하다"],["颈椎","jǐngzhuī","목뼈"],["劳损","láosǔn","무리해서 상하다"],["适时","shìshí","적절한 때에"]],"tr":["장자는 '포정해우' 이야기로, 일은 사물의 이치를 따라야만 여유 있게 해낼 수 있다고 말했다.","이번 고고학 발견은 창장강 유역 초기 문명의 기원에 대한 사람들의 인식을 완전히 바꿔 놓을지도 모른다.","수학자 화뤄겅은 독학으로 성공해 해석적 수론 등의 분야에서 온 세상이 주목하는 성과를 거두었다.","전문가들은 오래 고개를 숙이고 휴대폰을 보면 목뼈가 상하기 쉬우니 때때로 목을 움직여 주라고 당부한다."],"ow":[[["庖丁解牛","páo dīng jiě niú","백정이 소를 잡듯 능숙하다"],["游刃有余","yóu rèn yǒu yú","여유 있게 해내다"]],[["改写","gǎixiě","고쳐 쓰다"],["流域","liúyù","유역"],["起源","qǐyuán","기원"]],[["华罗庚","Huà Luógēng","화뤄겅(현대 수학자)"],["举世瞩目","jǔ shì zhǔ mù","온 세상이 주목하다"]],[["颈椎","jǐngzhuī","목뼈"],["劳损","láosǔn","무리해서 상하다"],["适时","shìshí","적절한 때에"]]]},{"o":["中医认为，人们如果把顺应四时的养生之道能长期坚持下去，就可以少生病、晚衰老。","“千里之行，始于足下”出自《道德经》，意在说明远大的目标要从一点一滴做起。","这种耐盐碱的水稻品种在沿海滩涂上试种成功，亩产突破了六百公斤。","战国时期修建的都江堰水利工程，至今仍在发挥着灌溉和防洪的作用。"],"a":0,"type":"능원동사 위치","why":"능원동사 “能”은 “把” 구 앞에 와야 한다. “把…能…”는 순서가 틀렸다.","fix":"中医认为，人们如果能把顺应四时的养生之道长期坚持下去，就可以少生病、晚衰老。","words":[["四时","sìshí","사계절"],["养生之道","yǎngshēng zhī dào","양생법"],["衰老","shuāilǎo","노쇠하다"],["千里之行","qiān lǐ zhī xíng","천 리 길"],["盐碱","yánjiǎn","염분과 알칼리"],["滩涂","tāntú","갯벌"],["都江堰","Dūjiāngyàn","두장옌(고대 수리 시설)"],["灌溉","guàngài","관개하다"]],"tr":["한의학에서는 사람이 사계절에 맞춘 양생법을 오래 꾸준히 지키면 병이 덜 나고 늙음도 늦출 수 있다고 본다.","'천 리 길도 한 걸음부터'는 《도덕경》에서 나온 말로, 큰 목표도 조금씩 차근차근 이뤄야 한다는 뜻이다.","염분과 알칼리에 강한 이 벼 품종은 바닷가 갯벌 시험 재배에 성공해 1무당 수확량이 600kg을 넘었다.","전국 시대에 만든 두장옌 수리 시설은 지금도 물을 대고 홍수를 막는 구실을 하고 있다."],"ow":[[["四时","sìshí","사계절"],["养生之道","yǎngshēng zhī dào","양생법"],["衰老","shuāilǎo","노쇠하다"]],[["千里之行","qiān lǐ zhī xíng","천 리 길"],["道德经","Dàodé Jīng","도덕경"],["一点一滴","yì diǎn yì dī","조금씩"]],[["盐碱","yánjiǎn","염분과 알칼리"],["滩涂","tāntú","갯벌"]],[["都江堰","Dūjiāngyàn","두장옌(고대 수리 시설)"],["灌溉","guàngài","관개하다"]]]},{"o":["刘备三顾茅庐，终于请得诸葛亮出山，这一佳话体现了求贤若渴的精神。","地震发生后，来自各地的救援队伍争分夺秒，昼夜不停地在废墟中搜寻幸存者。","这位年近百岁的老人，古典诗词对他至今仍怀有浓厚的兴趣，每天都要吟诵几首。","这项技术能将农作物秸秆转化为清洁燃料，既减少了污染，又提高了资源利用率。"],"a":2,"type":"개사구 위치","why":"“对”의 위치가 바뀌어 시가 노인에게 흥미를 가진 꼴이 됐다. “他对古典诗词”이라고 해야 한다.","fix":"这位年近百岁的老人对古典诗词至今仍怀有浓厚的兴趣，每天都要吟诵几首。","words":[["三顾茅庐","sān gù máo lú","삼고초려"],["出山","chūshān","세상에 나와 벼슬하다"],["佳话","jiāhuà","미담"],["求贤若渴","qiú xián ruò kě","목마르듯 인재를 구하다"],["争分夺秒","zhēng fēn duó miǎo","촌각을 다투다"],["废墟","fèixū","폐허"],["吟诵","yínsòng","읊조리다"],["秸秆","jiēgǎn","농작물 줄기"]],"tr":["유비는 세 번이나 초가집을 찾아가 마침내 제갈량을 세상에 나오게 했는데, 이 미담은 목마르듯 인재를 구하는 정신을 보여 준다.","지진이 나자 각지에서 온 구조대가 촌각을 다투며 밤낮없이 폐허 속에서 생존자를 찾았다.","백 살에 가까운 이 노인은 지금도 고전 시가에 깊은 흥미를 갖고 날마다 몇 수씩 읊는다.","이 기술은 농작물 줄기를 깨끗한 연료로 바꿀 수 있어 오염을 줄이고 자원 이용률도 높였다."],"ow":[[["三顾茅庐","sān gù máo lú","삼고초려"],["出山","chūshān","세상에 나와 벼슬하다"],["佳话","jiāhuà","미담"],["求贤若渴","qiú xián ruò kě","목마르듯 인재를 구하다"]],[["争分夺秒","zhēng fēn duó miǎo","촌각을 다투다"],["废墟","fèixū","폐허"]],[["吟诵","yínsòng","읊조리다"],["年近百岁","nián jìn bǎi suì","백 살에 가깝다"],["浓厚","nónghòu","짙다"]],[["秸秆","jiēgǎn","농작물 줄기"],["燃料","ránliào","연료"],["利用率","lìyònglǜ","이용률"]]]},{"o":["这座古城的城墙始建于明代洪武年间，是我国现存规模最大、保存最完整的古城墙之一。","两千多年来，后世对老子“道法自然”思想的影响极为深远，涉及哲学、宗教、艺术等诸多领域。","在专家的指导下，村民们用传统工艺重新烧制出了失传已久的青瓷。","陈景润证明了“1+2”，在哥德巴赫猜想的研究上取得了迄今为止最好的成果。"],"a":1,"type":"개사구 위치","why":"“对” 앞뒤가 바뀌어 후세가 노자에게 영향을 준 꼴이 됐다. “老子的思想对后世”라고 해야 한다.","fix":"两千多年来，老子“道法自然”的思想对后世的影响极为深远，涉及哲学、宗教、艺术等诸多领域。","words":[["洪武","Hóngwǔ","홍무(명 태조 연호)"],["道法自然","dào fǎ zì rán","도는 자연을 본받는다"],["诸多","zhūduō","여러"],["烧制","shāozhì","구워 만들다"],["青瓷","qīngcí","청자"],["陈景润","Chén Jǐngrùn","천징룬(현대 수학자)"],["哥德巴赫猜想","Gēdébāhè cāixiǎng","골드바흐 추측"],["迄今","qìjīn","지금까지"]],"tr":["이 옛 도시의 성벽은 명나라 홍무 연간에 처음 지어졌고, 중국에 남아 있는 것 가운데 규모가 가장 크고 가장 온전한 옛 성벽의 하나다.","2천여 년 동안 '도는 자연을 본받는다'는 노자 사상은 철학, 종교, 예술 등 여러 분야에 걸쳐 후대에 깊은 영향을 끼쳤다.","전문가의 지도 아래 마을 사람들은 전통 방식으로, 오래전 맥이 끊긴 청자를 다시 구워 냈다.","천징룬은 '1+2'를 증명해 골드바흐 추측 연구에서 지금까지 가장 좋은 성과를 냈다."],"ow":[[["洪武","Hóngwǔ","홍무(명 태조 연호)"],["始建","shǐjiàn","처음 짓다"],["现存","xiàncún","현존하다"]],[["道法自然","dào fǎ zì rán","도는 자연을 본받는다"],["诸多","zhūduō","여러"]],[["烧制","shāozhì","구워 만들다"],["青瓷","qīngcí","청자"]],[["陈景润","Chén Jǐngrùn","천징룬(현대 수학자)"],["哥德巴赫猜想","Gēdébāhè cāixiǎng","골드바흐 추측"],["迄今","qìjīn","지금까지"]]]},{"o":["孔子曾问礼于老子，这次会面成为后世儒道两家交流史上广为流传的一段佳话。","清代数学家李善兰与外国学者合作翻译西方数学著作，创造了“微分”“积分”等沿用至今的译名。","这位年轻的设计师将剪纸元素融入现代服装，作品一经发布便引起了轰动。","博物馆新近展出了一件精美的唐代出土于西安郊外的鎏金银壶，吸引了大批游客。"],"a":3,"type":"관형어 순서","why":"긴 동사구 관형어 “出土于西安郊外的”가 맨 앞에 와야 하는데 “精美的唐代” 뒤에 놓여 순서가 틀렸다.","fix":"博物馆新近展出了一件出土于西安郊外的精美的唐代鎏金银壶，吸引了大批游客。","words":[["新近","xīnjìn","최근"],["鎏金","liújīn","금도금"],["问礼","wènlǐ","예를 묻다"],["佳话","jiāhuà","미담"],["李善兰","Lǐ Shànlán","리산란(청 수학자)"],["沿用","yányòng","계속 쓰다"],["剪纸","jiǎnzhǐ","전지(종이 오리기 공예)"],["轰动","hōngdòng","센세이션을 일으키다"]],"tr":["공자는 일찍이 노자에게 예를 물었는데, 이 만남은 후대 유가와 도가의 교류사에서 널리 전해지는 미담이 되었다.","청나라 수학자 리산란은 외국 학자와 함께 서양 수학책을 번역하며 '미분', '적분'처럼 지금까지 쓰이는 번역어를 만들었다.","이 젊은 디자이너는 전지 공예 요소를 현대 의상에 녹여 내, 작품을 발표하자마자 큰 반향을 일으켰다.","박물관은 최근 시안 교외에서 출토된 정교한 당나라 금도금 은주전자 한 점을 전시해 많은 관람객을 끌어모았다."],"ow":[[["问礼","wènlǐ","예를 묻다"],["佳话","jiāhuà","미담"]],[["李善兰","Lǐ Shànlán","리산란(청 수학자)"],["沿用","yányòng","계속 쓰다"]],[["剪纸","jiǎnzhǐ","전지(종이 오리기 공예)"],["轰动","hōngdòng","센세이션을 일으키다"]],[["新近","xīnjìn","최근"],["鎏金","liújīn","금도금"]]]},{"o":["沈括是北宋时期杰出的一位在天文、数学、地理等领域都有建树的科学家。","鸟类的骨骼大多中空，既能减轻体重，又能保证足够的强度，非常适合飞行。","“画蛇添足”出自《战国策》，比喻做了多余的事，非但无益，反而不合适。","当地政府投入专项资金，对这条有着六百多年历史的古街进行了修缮。"],"a":0,"type":"관형어 순서","why":"수량사 “一位”는 묘사하는 말 “杰出的” 앞에 와야 하고, “杰出”은 명사 바로 앞에 두어야 한다.","fix":"沈括是北宋时期一位在天文、数学、地理等领域都有建树的杰出科学家。","words":[["沈括","Shěn Kuò","심괄(북송 과학자)"],["杰出","jiéchū","걸출하다"],["建树","jiànshù","업적"],["骨骼","gǔgé","골격"],["画蛇添足","huà shé tiān zú","사족을 달다"],["战国策","Zhànguó Cè","전국책"],["专项","zhuānxiàng","특정 항목용"],["修缮","xiūshàn","보수하다"]],"tr":["심괄은 북송 시대 천문, 수학, 지리 등 여러 분야에서 업적을 남긴 뛰어난 과학자다.","새의 뼈는 대부분 속이 비어 있어 몸무게를 줄이면서도 충분한 강도를 지켜, 날기에 아주 알맞다.","'뱀을 그리고 발을 더한다'는 《전국책》에서 나온 말로, 쓸데없는 일을 해서 도움이 되기는커녕 도리어 일을 그르치는 것을 비유한다.","현지 정부는 전용 자금을 들여 600여 년 역사의 이 옛 거리를 보수했다."],"ow":[[["沈括","Shěn Kuò","심괄(북송 과학자)"],["杰出","jiéchū","걸출하다"],["建树","jiànshù","업적"]],[["骨骼","gǔgé","골격"],["中空","zhōngkōng","속이 비다"],["强度","qiángdù","강도"]],[["画蛇添足","huà shé tiān zú","사족을 달다"],["战国策","Zhànguó Cè","전국책"]],[["专项","zhuānxiàng","특정 항목용"],["修缮","xiūshàn","보수하다"]]]},{"o":["“杞人忧天”的故事出自《列子》，后人用它来比喻缺乏根据、毫无必要的忧虑。","由于地下水被过度开采，华北平原部分地区出现了不同程度的地面沉降。","这次展览集中展出了亲笔批注的这位国学大师的二十余部线装书，引起了学界的关注。","这场持续了三天三夜的暴雨打乱了人们的出行计划，城区多处路段出现严重积水。"],"a":2,"type":"관형어 순서","why":"누구의 것인지 나타내는 “这位国学大师”가 맨 앞에 와야 한다. “亲笔批注的”가 그 앞에 있어 순서가 틀렸다.","fix":"这次展览集中展出了这位国学大师亲笔批注的二十余部线装书，引起了学界的关注。","words":[["杞人忧天","Qǐ rén yōu tiān","쓸데없는 걱정"],["列子","Lièzǐ","열자"],["开采","kāicǎi","채굴하다"],["沉降","chénjiàng","가라앉다"],["批注","pīzhù","평과 주석을 달다"],["国学","guóxué","중국 고전학"],["线装书","xiànzhuāngshū","실로 묶은 옛 책"],["积水","jīshuǐ","물이 고이다"]],"tr":["'기나라 사람의 하늘 걱정' 이야기는 《열자》에서 나왔고, 후대 사람들은 근거 없고 쓸데없는 걱정을 비유할 때 쓴다.","지하수를 지나치게 퍼 올린 탓에 화베이 평원 일부 지역에서 정도는 다르지만 땅이 꺼지는 일이 생겼다.","이번 전시는 이 국학 대가가 직접 평과 주석을 단 실로 묶은 옛 책 20여 권을 한데 모아 보여 주어 학계의 관심을 끌었다.","사흘 밤낮 이어진 폭우로 사람들의 외출 계획이 엉망이 되었고, 시내 곳곳의 도로가 심하게 물에 잠겼다."],"ow":[[["杞人忧天","Qǐ rén yōu tiān","쓸데없는 걱정"],["列子","Lièzǐ","열자"]],[["开采","kāicǎi","채굴하다"],["沉降","chénjiàng","가라앉다"]],[["批注","pīzhù","평과 주석을 달다"],["国学","guóxué","중국 고전학"],["线装书","xiànzhuāngshū","실로 묶은 옛 책"]],[["积水","jīshuǐ","물이 고이다"],["暴雨","bàoyǔ","폭우"],["路段","lùduàn","도로 구간"]]]},{"o":["孔子的弟子及再传弟子将孔子的言行记录下来，编纂成了《论语》。","由于长期缺乏维护，这座木结构的古戏台已经摇摇欲坠，亟待抢修。","“卧薪尝胆”说的是越王勾践兵败后刻苦自励、发愤图强，最终灭掉吴国的故事。","考察队计划先对采集到的土壤样本进行化验分析，再深入无人区广泛采集不同海拔的样本。"],"a":3,"type":"사건 순서","why":"표본을 먼저 모아야 분석할 수 있는데, “先…化验分析，再…采集”로 순서가 거꾸로다.","fix":"考察队计划先深入无人区广泛采集不同海拔的土壤样本，再对采集到的样本进行化验分析。","words":[["再传弟子","zàichuán dìzǐ","제자의 제자"],["编纂","biānzuǎn","편찬하다"],["摇摇欲坠","yáo yáo yù zhuì","곧 무너질 듯하다"],["亟待","jídài","시급히 ~해야 하다"],["卧薪尝胆","wò xīn cháng dǎn","와신상담"],["发愤图强","fā fèn tú qiáng","분발해 강해지려 하다"],["化验","huàyàn","화학 분석하다"],["无人区","wúrénqū","무인 지대"]],"tr":["공자의 제자와 그 제자의 제자들이 공자의 말과 행동을 기록해 《논어》로 엮었다.","오랫동안 손보지 않아 이 나무로 지은 옛 무대는 곧 무너질 듯해 서둘러 보수해야 한다.","'와신상담'은 월왕 구천이 싸움에 진 뒤 스스로를 다그치며 분발해 마침내 오나라를 멸망시킨 이야기다.","탐사대는 먼저 모은 흙 표본을 화학 분석한 뒤, 무인 지대 깊숙이 들어가 여러 고도의 표본을 널리 모을 계획이다."],"ow":[[["再传弟子","zàichuán dìzǐ","제자의 제자"],["编纂","biānzuǎn","편찬하다"]],[["摇摇欲坠","yáo yáo yù zhuì","곧 무너질 듯하다"],["亟待","jídài","시급히 ~해야 하다"]],[["卧薪尝胆","wò xīn cháng dǎn","와신상담"],["发愤图强","fā fèn tú qiáng","분발해 강해지려 하다"]],[["化验","huàyàn","화학 분석하다"],["无人区","wúrénqū","무인 지대"]]]},{"o":["鉴于该物种野外种群数量急剧下降，有关部门已将其列为国家一级保护动物。","会议上，与会专家们深入讨论并广泛听取了基层代表关于古村落保护的意见。","“唇亡齿寒”源于春秋时期晋国借道伐虢的故事，比喻双方关系密切、利害相关。","夏季风从海洋上带来大量水汽，因此我国东部地区的降水多集中在夏季。"],"a":1,"type":"사건 순서","why":"의견은 먼저 듣고 나서 토론해야 하는데 “讨论并听取”로 순서가 거꾸로다.","fix":"会议上，与会专家们广泛听取并深入讨论了基层代表关于古村落保护的意见。","words":[["鉴于","jiànyú","~을 감안하여"],["急剧","jíjù","급격히"],["与会","yùhuì","회의에 참석하다"],["基层","jīcéng","현장, 말단"],["古村落","gǔcūnluò","옛 마을"],["唇亡齿寒","chún wáng chǐ hán","순망치한"],["虢","Guó","괵(춘추 시대 나라)"],["水汽","shuǐqì","수증기"]],"tr":["이 종의 야생 개체 수가 급격히 줄어든 점을 고려해 관련 부서는 이 동물을 국가 1급 보호 동물로 지정했다.","회의에서 참석한 전문가들은 옛 마을 보호에 관한 현장 대표들의 의견을 깊이 토론하고 널리 들었다.","'입술이 없으면 이가 시리다'는 춘추 시대 진나라가 길을 빌려 괵나라를 친 이야기에서 나왔으며, 두 쪽의 관계가 가까워 이해가 맞물려 있음을 비유한다.","여름 계절풍이 바다에서 많은 수증기를 몰고 오기 때문에 중국 동부의 비는 대부분 여름에 집중된다."],"ow":[[["鉴于","jiànyú","~을 감안하여"],["急剧","jíjù","급격히"]],[["与会","yùhuì","회의에 참석하다"],["基层","jīcéng","현장, 말단"],["古村落","gǔcūnluò","옛 마을"]],[["唇亡齿寒","chún wáng chǐ hán","순망치한"],["虢","Guó","괵(춘추 시대 나라)"]],[["水汽","shuǐqì","수증기"],["季风","jìfēng","계절풍"],["降水","jiàngshuǐ","강수"]]]}],[{"o":["这种生长在沙漠中的植物，根系可以深入地下数十米，以吸取深层的水分。","老子认为，只有顺应万物的本性而不强加干预，天下就能实现长治久安。","这家百年老店宁可少赚一些钱，也不肯在原料上以次充好。","公元一〇五年前后，蔡伦改进了造纸术，使纸张逐渐成为普遍使用的书写材料。"],"a":1,"type":"짝 오류","why":"“只有”는 “才”와 짝을 이루어야 하는데 “就”를 썼다.","fix":"老子认为，只有顺应万物的本性而不强加干预，天下才能实现长治久安。","words":[["根系","gēnxì","뿌리 계통"],["本性","běnxìng","본성"],["强加","qiángjiā","억지로 가하다"],["长治久安","cháng zhì jiǔ ān","오래도록 태평하다"],["以次充好","yǐ cì chōng hǎo","나쁜 것을 좋은 것으로 속이다"],["蔡伦","Cài Lún","채륜"],["造纸术","zàozhǐshù","제지술"]],"tr":["사막에서 자라는 이 식물은 뿌리가 땅속 수십 미터까지 뻗어 깊은 곳의 물을 빨아들인다.","노자는 만물의 본성을 따르고 억지로 간섭하지 않아야만 천하가 오래도록 태평할 수 있다고 보았다.","이 100년 된 가게는 돈을 조금 덜 벌지언정 재료에서 나쁜 것을 좋은 것인 양 속이려 하지 않는다.","서기 105년 무렵 채륜이 제지술을 개량해, 종이가 점차 널리 쓰이는 필기 재료가 되었다."],"ow":[[["根系","gēnxì","뿌리 계통"],["吸取","xīqǔ","빨아들이다"],["沙漠","shāmò","사막"]],[["本性","běnxìng","본성"],["强加","qiángjiā","억지로 가하다"],["长治久安","cháng zhì jiǔ ān","오래도록 태평하다"]],[["以次充好","yǐ cì chōng hǎo","나쁜 것을 좋은 것으로 속이다"],["宁可","nìngkě","차라리"],["原料","yuánliào","원료"]],[["蔡伦","Cài Lún","채륜"],["造纸术","zàozhǐshù","제지술"]]]},{"o":["庄子拒绝了楚王的聘请，他认为既然入朝为官难免身不由己，才宁愿像乌龟一样拖着尾巴在泥里自在爬行。","这项研究既然已经取得了阶段性成果，就应当尽快组织专家进行论证。","尽管人工智能发展迅猛，但它在情感理解方面仍远远无法与人类相比。","苏州评弹用吴语说唱，曲调婉转柔美，素有“中国最美的声音”之称。"],"a":0,"type":"짝 오류","why":"“既然”은 “就/那就”와 짝을 이루어야 하는데 “才”를 썼다.","fix":"庄子拒绝了楚王的聘请，他认为既然入朝为官难免身不由己，那就宁愿像乌龟一样拖着尾巴在泥里自在爬行。","words":[["聘请","pìnqǐng","초빙하다"],["身不由己","shēn bù yóu jǐ","제 뜻대로 할 수 없다"],["阶段性","jiēduànxìng","단계적"],["论证","lùnzhèng","검증하다"],["迅猛","xùnměng","빠르고 맹렬하다"],["评弹","píngtán","평탄(쑤저우 설창 예술)"],["婉转","wǎnzhuǎn","(소리가) 부드럽게 굽이치다"]],"tr":["장자는 초왕의 초빙을 거절하며, 조정에 들어가 벼슬하면 제 뜻대로 살 수 없으니 차라리 거북처럼 꼬리를 끌며 진흙 속을 자유롭게 기어다니겠다고 했다.","이 연구가 이미 단계적인 성과를 냈으니 서둘러 전문가를 모아 검증해야 한다.","인공지능이 빠르게 발전하고 있지만 감정을 이해하는 면에서는 아직 사람에게 한참 못 미친다.","쑤저우 평탄은 우 지방 말로 말하고 노래하며, 가락이 부드럽고 아름다워 예부터 '중국에서 가장 아름다운 소리'로 불린다."],"ow":[[["聘请","pìnqǐng","초빙하다"],["身不由己","shēn bù yóu jǐ","제 뜻대로 할 수 없다"]],[["阶段性","jiēduànxìng","단계적"],["论证","lùnzhèng","검증하다"]],[["迅猛","xùnměng","빠르고 맹렬하다"],["人工智能","réngōng zhìnéng","인공지능"],["尽管","jǐnguǎn","비록 ~이지만"]],[["评弹","píngtán","평탄(쑤저우 설창 예술)"],["婉转","wǎnzhuǎn","(소리가) 부드럽게 굽이치다"]]]},{"o":["汉武帝时颁行的《太初历》，是我国第一部有完整文字记载的历法。","清初学者梅文鼎一生致力于会通中西历算，被誉为“国朝历算第一名家”。","古人常说，一个人只要能做到“己所不欲，勿施于人”，才能真正赢得他人的尊重与信任。","随着年龄增长，人体骨骼中的钙质会逐渐流失，因此老年人更要注意补钙。"],"a":2,"type":"짝 오류","why":"“只要”는 “就”와, “才”는 “只有”와 짝인데 “只要…才”로 섞어 썼다.","fix":"古人常说，一个人只有做到“己所不欲，勿施于人”，才能真正赢得他人的尊重与信任。","words":[["太初历","Tàichū Lì","태초력(한나라 역법)"],["颁行","bānxíng","공포해 시행하다"],["梅文鼎","Méi Wéndǐng","매문정(청초 학자)"],["会通","huìtōng","융합해 통하다"],["历算","lìsuàn","역법과 산학"],["己所不欲，勿施于人","jǐ suǒ bú yù, wù shī yú rén","내가 원치 않는 것을 남에게 하지 마라"],["钙质","gàizhì","칼슘"],["流失","liúshī","빠져나가다"]],"tr":["한 무제 때 반포된 《태초력》은 중국에서 처음으로 완전한 글 기록이 남은 역법이다.","청나라 초 학자 매문정은 평생 중국과 서양의 역법과 산학을 하나로 꿰는 데 힘써 '이 왕조 최고의 역산가'로 불렸다.","옛사람들은 '내가 원치 않는 것을 남에게 하지 말라'를 지켜야만 남의 존경과 믿음을 참으로 얻을 수 있다고 했다.","나이가 들면 뼛속 칼슘이 점점 빠져나가므로 노인은 칼슘 보충에 더 신경 써야 한다."],"ow":[[["太初历","Tàichū Lì","태초력(한나라 역법)"],["颁行","bānxíng","공포해 시행하다"]],[["梅文鼎","Méi Wéndǐng","매문정(청초 학자)"],["会通","huìtōng","융합해 통하다"],["历算","lìsuàn","역법과 산학"]],[["己所不欲，勿施于人","jǐ suǒ bú yù, wù shī yú rén","내가 원치 않는 것을 남에게 하지 마라"],["赢得","yíngdé","얻다"],["信任","xìnrèn","신뢰"]],[["钙质","gàizhì","칼슘"],["流失","liúshī","빠져나가다"]]]},{"o":["历史上，伯乐善于相马的故事广为流传，人们常用“伯乐”来比喻善于发现和选拔人才的人。","我们之所以要了解历史，是因为历史能为当下的选择提供借鉴。","不仅孔子本人十分重视音乐教育，他的许多弟子也都精通音律。","不但《齐民要术》系统总结了北魏以前黄河流域的农业生产经验，而且对后世农学的发展影响深远。"],"a":3,"type":"관련사 위치","why":"앞뒤 주어가 같이 《齐民要术》이므로 “不但”은 주어 뒤에 와야 한다.","fix":"《齐民要术》不但系统总结了北魏以前黄河流域的农业生产经验，而且对后世农学的发展影响深远。","words":[["伯乐","Bólè","백락(말 감정의 명인)"],["相马","xiàngmǎ","말을 감정하다"],["选拔","xuǎnbá","선발하다"],["借鉴","jièjiàn","본보기"],["音律","yīnlǜ","음률"],["齐民要术","Qímín Yàoshù","제민요술(농서)"],["北魏","Běi Wèi","북위"],["农学","nóngxué","농학"]],"tr":["예로부터 말을 잘 알아본 백락의 이야기가 널리 전해져, 사람들은 인재를 잘 찾아내고 뽑는 사람을 '백락'에 빗댄다.","우리가 역사를 알아야 하는 까닭은 역사가 오늘의 선택에 본보기를 주기 때문이다.","공자 자신이 음악 교육을 매우 중시했을 뿐 아니라 그의 많은 제자도 음률에 밝았다.","《제민요술》은 북위 이전 황허 유역의 농업 생산 경험을 체계적으로 정리했고, 후대 농학 발전에도 깊은 영향을 끼쳤다."],"ow":[[["伯乐","Bólè","백락(말 감정의 명인)"],["相马","xiàngmǎ","말을 감정하다"],["选拔","xuǎnbá","선발하다"]],[["借鉴","jièjiàn","본보기"],["之所以","zhīsuǒyǐ","~한 까닭은"],["当下","dāngxià","지금, 현재"]],[["音律","yīnlǜ","음률"],["弟子","dìzǐ","제자"],["精通","jīngtōng","정통하다"]],[["齐民要术","Qímín Yàoshù","제민요술(농서)"],["北魏","Běi Wèi","북위"],["农学","nóngxué","농학"]]]},{"o":["唐太宗不但能够虚心纳谏，而且魏征也敢于犯颜直谏，君臣之间相得益彰。","在长期的进化过程中，仙人掌的叶子逐渐演变成了刺，以减少水分的蒸发。","这一地区雨热同期，土壤肥沃，自古以来便是重要的粮食产区。","这项公益活动旨在帮助留守儿童，让他们在课余时间也能得到陪伴与关爱。"],"a":0,"type":"관련사 위치","why":"앞뒤 주어가 다르므로(唐太宗, 魏征) “不但”은 첫 주어 앞에 와야 한다.","fix":"不但唐太宗能够虚心纳谏，而且魏征也敢于犯颜直谏，君臣之间相得益彰。","words":[["纳谏","nàjiàn","간언을 받아들이다"],["犯颜直谏","fàn yán zhí jiàn","임금 안색을 거슬러 바로 간하다"],["相得益彰","xiāng dé yì zhāng","서로 도와 더 빛나다"],["仙人掌","xiānrénzhǎng","선인장"],["蒸发","zhēngfā","증발하다"],["肥沃","féiwò","비옥하다"],["旨在","zhǐzài","~에 목적이 있다"],["留守儿童","liúshǒu értóng","부모가 외지로 떠나 남겨진 아이"]],"tr":["당 태종은 간언을 겸허히 받아들였고 위징 또한 임금의 안색을 거스르며 바른말을 해, 임금과 신하가 서로를 더욱 빛냈다.","오랜 진화 과정에서 선인장의 잎은 점차 가시로 바뀌어 물이 증발하는 것을 줄였다.","이 지역은 비와 더위가 같은 철에 오고 흙이 기름져 예부터 중요한 곡창 지대였다.","이 공익 활동은 부모와 떨어져 사는 아이들을 도와, 방과 후에도 곁에서 돌보고 아껴 주는 손길을 받게 하려는 것이다."],"ow":[[["纳谏","nàjiàn","간언을 받아들이다"],["犯颜直谏","fàn yán zhí jiàn","임금 안색을 거슬러 바로 간하다"],["相得益彰","xiāng dé yì zhāng","서로 도와 더 빛나다"]],[["仙人掌","xiānrénzhǎng","선인장"],["蒸发","zhēngfā","증발하다"]],[["肥沃","féiwò","비옥하다"],["雨热同期","yǔ rè tóng qī","비와 더위가 같은 철에 오다"],["产区","chǎnqū","산지"]],[["旨在","zhǐzài","~에 목적이 있다"],["留守儿童","liúshǒu értóng","부모가 외지로 떠나 남겨진 아이"]]]},{"o":["唐代文学家韩愈在《师说》中提出“师者，所以传道受业解惑也”，阐明了教师的职责。","由于海拔高、昼夜温差大，这里出产的苹果口感脆甜，糖分含量很高。","这位学者的著作不但在世界范围内引起了强烈反响，而且在国内学术界也颇受关注。","金元之际的数学家李冶在《测圆海镜》中系统总结了“天元术”，这是一种借助符号列方程的方法。"],"a":2,"type":"논리 관계","why":"“不但…而且”는 뒤가 더 큰 범위여야 하는데, 세계에서 국내로 거꾸로 좁아졌다.","fix":"这位学者的著作不但在国内学术界颇受关注，而且在世界范围内也引起了强烈反响。","words":[["韩愈","Hán Yù","한유(당 문학가)"],["解惑","jiěhuò","의문을 풀다"],["阐明","chǎnmíng","밝히다"],["昼夜","zhòuyè","낮과 밤"],["反响","fǎnxiǎng","반향"],["李冶","Lǐ Yě","이야(금원 수학자)"],["天元术","tiānyuánshù","천원술(방정식 세우는 법)"],["测圆海镜","Cèyuán Hǎijìng","측원해경(수학서)"]],"tr":["당나라 문학가 한유는 《사설》에서 '스승이란 도를 전하고 학업을 가르치며 의문을 풀어 주는 사람'이라 하여 교사의 책임을 밝혔다.","고도가 높고 낮과 밤의 기온 차가 커서 이곳 사과는 아삭하고 달며 당분이 많다.","이 학자의 저서는 세계적으로 큰 반향을 일으켰고 국내 학계에서도 꽤 주목을 받았다.","금원 교체기의 수학자 이야는 《측원해경》에서 기호로 방정식을 세우는 방법인 '천원술'을 체계적으로 정리했다."],"ow":[[["韩愈","Hán Yù","한유(당 문학가)"],["解惑","jiěhuò","의문을 풀다"],["阐明","chǎnmíng","밝히다"]],[["昼夜","zhòuyè","낮과 밤"],["海拔","hǎibá","해발"],["温差","wēnchā","기온 차"]],[["反响","fǎnxiǎng","반향"],["著作","zhùzuò","저서"],["颇","pō","꽤"]],[["李冶","Lǐ Yě","이야(금원 수학자)"],["天元术","tiānyuánshù","천원술(방정식 세우는 법)"],["测圆海镜","Cèyuán Hǎijìng","측원해경(수학서)"]]]},{"o":["这款面向老年人设计的应用程序上线不到一个月，下载量就突破了一千万次。","西汉的匡衡自幼家境贫寒，却买不起照明用的蜡烛，于是便凿穿墙壁借邻居家的烛光读书。","秦汉时期修建的驰道以咸阳为中心向四方延伸，是我国最早的“国道”。","研究发现，经常与他人进行深度交流的人，往往拥有更强的幸福感。"],"a":1,"type":"논리 관계","why":"집이 가난해서 초를 못 산 것은 원인과 결과인데, 반대를 뜻하는 “却”를 썼다.","fix":"西汉的匡衡自幼家境贫寒，买不起照明用的蜡烛，于是便凿穿墙壁借邻居家的烛光读书。","words":[["上线","shàngxiàn","출시되다"],["匡衡","Kuāng Héng","광형(서한 학자)"],["家境贫寒","jiājìng pínhán","집안이 가난하다"],["蜡烛","làzhú","초"],["凿穿","záochuān","뚫다"],["驰道","chídào","치도(진나라 국도)"],["咸阳","Xiányáng","셴양"],["延伸","yánshēn","뻗어 나가다"]],"tr":["노인을 위해 만든 이 앱은 출시 한 달도 안 돼 내려받기 1천만 회를 넘었다.","서한의 광형은 어려서 집이 가난해 불 밝힐 초를 살 수 없자, 벽에 구멍을 뚫어 이웃집 불빛을 빌려 책을 읽었다.","진한 시대에 닦은 치도는 셴양을 중심으로 사방으로 뻗었으며, 중국 최초의 '국도'였다.","연구에 따르면 남과 자주 깊이 있는 대화를 나누는 사람은 대체로 행복감이 더 크다."],"ow":[[["上线","shàngxiàn","출시되다"],["应用程序","yìngyòng chéngxù","앱"],["突破","tūpò","넘어서다"]],[["匡衡","Kuāng Héng","광형(서한 학자)"],["家境贫寒","jiājìng pínhán","집안이 가난하다"],["蜡烛","làzhú","초"],["凿穿","záochuān","뚫다"]],[["驰道","chídào","치도(진나라 국도)"],["咸阳","Xiányáng","셴양"],["延伸","yánshēn","뻗어 나가다"]],[["深度","shēndù","깊이 있는"],["幸福感","xìngfúgǎn","행복감"]]]},{"o":["“集腋成裘”的意思是狐狸腋下的皮虽小，聚集起来就能缝成一件皮袍，比喻积少成多。","这种新型电池充电速度快、使用寿命长，有望在电动汽车领域得到广泛应用。","这片原始森林中栖息着数百种珍稀动物，被誉为“物种基因库”。","王安石变法的某些措施在执行过程中走了样，不但没有减轻百姓的负担，而且使不少农户背上了更沉重的债务。"],"a":3,"type":"논리 관계","why":"기대와 반대 결과를 말하므로 “不但没有…，反而…”이어야 하는데 “而且”를 썼다.","fix":"王安石变法的某些措施在执行过程中走了样，不但没有减轻百姓的负担，反而使不少农户背上了更沉重的债务。","words":[["集腋成裘","jí yè chéng qiú","티끌 모아 태산"],["皮袍","pípáo","가죽 두루마기"],["积少成多","jī shǎo chéng duō","적은 것이 쌓여 많아지다"],["栖息","qīxī","서식하다"],["基因库","jīyīnkù","유전자 은행"],["变法","biànfǎ","법제 개혁"],["走样","zǒuyàng","본래 모습을 잃다"],["债务","zhàiwù","빚"]],"tr":["'여우 겨드랑이 털을 모아 가죽옷을 만든다'는 말은 겨드랑이 가죽은 작아도 모으면 가죽 두루마기 한 벌을 지을 수 있다는 뜻으로, 적은 것이 쌓여 많아짐을 비유한다.","이 신형 배터리는 충전이 빠르고 수명이 길어 전기차 분야에서 널리 쓰일 것으로 기대된다.","이 원시림에는 수백 종의 희귀 동물이 살고 있어 '생물종 유전자 은행'으로 불린다.","왕안석 변법의 일부 조치는 시행 과정에서 본뜻을 잃어, 백성의 부담을 덜어 주기는커녕 많은 농가에 더 무거운 빚을 지웠다."],"ow":[[["集腋成裘","jí yè chéng qiú","티끌 모아 태산"],["皮袍","pípáo","가죽 두루마기"],["积少成多","jī shǎo chéng duō","적은 것이 쌓여 많아지다"]],[["寿命","shòumìng","수명"],["有望","yǒuwàng","~할 가망이 있다"]],[["栖息","qīxī","서식하다"],["基因库","jīyīnkù","유전자 은행"]],[["变法","biànfǎ","법제 개혁"],["债务","zhàiwù","빚"]]]},{"o":["道家“祸兮福之所倚，福兮祸之所伏”的观点，蕴含着朴素的辩证法思想。","研究表明，儿童时期养成良好的阅读习惯，对其一生的发展都大有裨益。","对于如何评价秦始皇的历史功过上，史学界至今仍存在着较大分歧。","位于河南登封的元代观星台，是我国现存最古老的天文台建筑之一。"],"a":2,"type":"개사 섞임","why":"“对于…”와 “在…上”을 섞어 “对于…上”이 됐다. 둘 중 하나만 써야 한다.","fix":"在如何评价秦始皇的历史功过上，史学界至今仍存在着较大分歧。","words":[["祸兮福之所倚","huò xī fú zhī suǒ yǐ","화 속에 복이 기대어 있다"],["蕴含","yùnhán","담고 있다"],["辩证法","biànzhèngfǎ","변증법"],["裨益","bìyì","도움, 이익"],["功过","gōngguò","공과"],["分歧","fēnqí","의견 차이"],["登封","Dēngfēng","덩펑(허난성 도시)"],["观星台","guānxīngtái","관성대(천문대)"]],"tr":["도가의 '화는 복이 기대는 곳이요, 복은 화가 숨는 곳이다'라는 관점에는 소박한 변증법 사상이 담겨 있다.","연구에 따르면 어린 시절 좋은 독서 습관을 들이면 평생의 성장에 큰 도움이 된다.","진시황의 역사적 공과를 어떻게 평가할지를 두고 사학계에는 지금도 의견이 크게 갈린다.","허난성 덩펑의 원나라 관성대는 중국에 남아 있는 가장 오래된 천문대 건축 가운데 하나다."],"ow":[[["祸兮福之所倚","huò xī fú zhī suǒ yǐ","화 속에 복이 기대어 있다"],["蕴含","yùnhán","담고 있다"],["辩证法","biànzhèngfǎ","변증법"]],[["裨益","bìyì","도움, 이익"],["养成","yǎngchéng","기르다"],["大有裨益","dà yǒu bì yì","크게 도움이 되다"]],[["功过","gōngguò","공과"],["分歧","fēnqí","의견 차이"]],[["登封","Dēngfēng","덩펑(허난성 도시)"],["观星台","guānxīngtái","관성대(천문대)"]]]},{"o":["老匠人的言传身教下，这批年轻学徒很快掌握了传统榫卯结构的制作要领。","夜间人工照明过度，会扰乱许多动物的生物钟，甚至干扰海龟幼崽爬向大海的方向。","“老骥伏枥，志在千里”出自曹操的诗作，常用来形容人虽年老仍怀有远大抱负。","这家企业在国际市场上站稳脚跟后，并没有满足于现状，而是继续在技术创新上加大投入。"],"a":0,"type":"개사 빠짐","why":"“…下”는 “在”와 함께 “在…下”로 써야 하는데 “在”가 빠졌다.","fix":"在老匠人的言传身教下，这批年轻学徒很快掌握了传统榫卯结构的制作要领。","words":[["言传身教","yán chuán shēn jiào","말과 행동으로 가르치다"],["学徒","xuétú","견습생"],["榫卯","sǔnmǎo","장부 이음"],["要领","yàolǐng","요령"],["生物钟","shēngwùzhōng","생체 시계"],["幼崽","yòuzǎi","새끼"],["老骥伏枥","lǎo jì fú lì","늙은 준마가 마구간에 엎드리다"],["站稳脚跟","zhànwěn jiǎogēn","발판을 굳히다"]],"tr":["늙은 장인이 말과 행동으로 가르친 덕분에 이 젊은 견습생들은 전통 장부 이음 구조를 만드는 요령을 빨리 익혔다.","밤에 인공조명이 지나치면 많은 동물의 생체 시계가 흐트러지고, 심지어 새끼 바다거북이 바다로 기어가는 방향까지 방해받는다.","'늙은 준마가 마구간에 엎드려 있어도 뜻은 천 리에 있다'는 조조의 시에서 나온 말로, 나이가 들어도 큰 뜻을 품은 사람을 나타낼 때 쓴다.","이 기업은 국제 시장에 발판을 굳힌 뒤에도 현실에 만족하지 않고 기술 혁신에 투자를 계속 늘렸다."],"ow":[[["言传身教","yán chuán shēn jiào","말과 행동으로 가르치다"],["学徒","xuétú","견습생"],["榫卯","sǔnmǎo","장부 이음"],["要领","yàolǐng","요령"]],[["生物钟","shēngwùzhōng","생체 시계"],["幼崽","yòuzǎi","새끼"]],[["老骥伏枥","lǎo jì fú lì","늙은 준마가 마구간에 엎드리다"],["志在千里","zhì zài qiān lǐ","뜻이 천 리에 있다"],["抱负","bàofù","포부"],["曹操","Cáo Cāo","조조"]],[["站稳脚跟","zhànwěn jiǎogēn","발판을 굳히다"],["现状","xiànzhuàng","현재 상태"],["创新","chuàngxīn","혁신"]]]}],[{"o":["老子说“知人者智，自知者明”，意思是能了解别人的人是聪明的，能认识自己的人才算是明智的。","这条古道曾是川藏之间运送茶叶和马匹的重要通道，被称为“茶马古道”。","为了避免古建筑的木构件在梅雨季节不发生霉变和虫蛀，工作人员提前采取了防潮措施。","实验结果显示，经常听舒缓音乐的奶牛，产奶量会有所提高。"],"a":2,"type":"이중 부정","why":"“避免”(피하다)에 “不”를 더해 ‘곰팡이가 안 생기는 것을 피한다’는 반대 뜻이 됐다.","fix":"为了避免古建筑的木构件在梅雨季节发生霉变和虫蛀，工作人员提前采取了防潮措施。","words":[["知人者智","zhī rén zhě zhì","남을 아는 자는 지혜롭다"],["茶马古道","Chámǎ Gǔdào","차마고도"],["木构件","mùgòujiàn","목조 부재"],["梅雨","méiyǔ","장마"],["霉变","méibiàn","곰팡이로 변질되다"],["虫蛀","chóngzhù","벌레 먹다"],["防潮","fángcháo","습기를 막다"],["舒缓","shūhuǎn","느긋하고 부드럽다"]],"tr":["노자는 '남을 아는 자는 지혜롭고 자신을 아는 자는 밝다'고 했는데, 남을 아는 사람은 영리하고 자신을 아는 사람이야말로 현명하다는 뜻이다.","이 옛길은 쓰촨과 티베트 사이에서 차와 말을 실어 나르던 중요한 통로로, '차마고도'라고 불린다.","고건축의 목조 부재에 장마철 곰팡이가 슬거나 벌레가 먹지 않도록 직원들이 미리 습기 막는 조치를 했다.","실험 결과, 부드러운 음악을 자주 들은 젖소는 젖 생산량이 어느 정도 늘었다."],"ow":[[["知人者智","zhī rén zhě zhì","남을 아는 자는 지혜롭다"],["自知者明","zì zhī zhě míng","자신을 아는 자는 밝다"],["明智","míngzhì","현명하다"]],[["茶马古道","Chámǎ Gǔdào","차마고도"],["川藏","Chuān-Zàng","쓰촨과 티베트"],["通道","tōngdào","통로"]],[["木构件","mùgòujiàn","목조 부재"],["梅雨","méiyǔ","장마"],["霉变","méibiàn","곰팡이로 변질되다"],["虫蛀","chóngzhù","벌레 먹다"],["防潮","fángcháo","습기를 막다"]],[["舒缓","shūhuǎn","느긋하고 부드럽다"],["奶牛","nǎiniú","젖소"],["有所","yǒusuǒ","어느 정도"]]]},{"o":["这种昆虫在幼虫阶段生活在水中，羽化后才离开水面飞向陆地。","初次登上舞台的演员难免会紧张，这时适当的深呼吸能帮助他们放松下来。","这家网站汇集了全国各地的方言录音，为语言研究者提供了宝贵的资料。","任何人都不能否认，诸子百家的争鸣不是中国思想史上最为璀璨的篇章之一。"],"a":3,"type":"삼중 부정","why":"“不能”, “否认”, “不是”가 겹쳐 ‘제자백가 논쟁은 빛나는 장이 아니다’라는 반대 뜻이 됐다.","fix":"任何人都不能否认，诸子百家的争鸣是中国思想史上最为璀璨的篇章之一。","words":[["幼虫","yòuchóng","애벌레"],["羽化","yǔhuà","날개 달린 성충이 되다"],["难免","nánmiǎn","~하기 마련이다"],["汇集","huìjí","모으다"],["方言","fāngyán","방언"],["否认","fǒurèn","부인하다"],["争鸣","zhēngmíng","논쟁하다"],["璀璨","cuǐcàn","찬란하다"]],"tr":["이 곤충은 애벌레 때 물속에 살다가 날개 달린 성충이 된 뒤에야 물을 떠나 뭍으로 날아간다.","처음 무대에 오르는 배우는 긴장하기 마련인데, 이때 적당히 깊게 숨을 쉬면 마음을 푸는 데 도움이 된다.","이 웹사이트는 전국 각지의 방언 녹음을 모아 언어 연구자에게 귀한 자료를 제공했다.","제자백가의 논쟁이 중국 사상사에서 가장 찬란한 장 가운데 하나라는 것은 누구도 부정할 수 없다."],"ow":[[["幼虫","yòuchóng","애벌레"],["羽化","yǔhuà","날개 달린 성충이 되다"]],[["难免","nánmiǎn","~하기 마련이다"],["舞台","wǔtái","무대"],["适当","shìdàng","적당하다"]],[["汇集","huìjí","모으다"],["方言","fāngyán","방언"]],[["否认","fǒurèn","부인하다"],["争鸣","zhēngmíng","논쟁하다"],["璀璨","cuǐcàn","찬란하다"]]]},{"o":["一时的失败未必不是好事，它往往能让人看清自身的不足。","古人告诫后学，读书切忌不要囫囵吞枣、不求甚解，而应当熟读精思、融会贯通。","明清两代设立钦天监，专门负责观测天象、推算历法和编制历书。","参观过秦始皇兵马俑的游客，无不为其宏大的规模和高超的工艺所折服。"],"a":1,"type":"이중 부정","why":"“切忌”가 이미 ‘절대 하지 마라’는 뜻이라 “不要”를 더하면 뜻이 뒤집힌다.","fix":"古人告诫后学，读书切忌囫囵吞枣、不求甚解，而应当熟读精思、融会贯通。","words":[["未必","wèibì","꼭 ~한 것은 아니다"],["切忌","qièjì","절대 삼가다"],["囫囵吞枣","hú lún tūn zǎo","대충 통째로 삼키다"],["不求甚解","bù qiú shèn jiě","깊이 이해하려 하지 않다"],["融会贯通","róng huì guàn tōng","두루 꿰뚫어 이해하다"],["钦天监","Qīntiānjiān","흠천감(천문 관청)"],["天象","tiānxiàng","천문 현상"],["折服","zhéfú","감탄해 탄복하다"]],"tr":["한때의 실패가 꼭 나쁜 일만은 아니다. 그것이 자신의 부족함을 똑똑히 보게 해 주는 경우가 많다.","옛사람들은 후학에게 책을 대충 통째로 삼키고 깊이 이해하려 하지 않는 것을 절대 삼가고, 익숙하게 읽고 깊이 생각해 두루 꿰뚫으라고 타일렀다.","명청 두 왕조는 흠천감을 두어 천문 현상 관측, 역법 계산, 달력 편찬을 전담하게 했다.","진시황 병마용을 본 관광객은 누구나 그 거대한 규모와 뛰어난 솜씨에 탄복한다."],"ow":[[["未必","wèibì","꼭 ~한 것은 아니다"],["未必不是","wèibì bú shì","꼭 ~이 아닌 것은 아니다"],["不足","bùzú","부족함"]],[["切忌","qièjì","절대 삼가다"],["囫囵吞枣","hú lún tūn zǎo","대충 통째로 삼키다"],["不求甚解","bù qiú shèn jiě","깊이 이해하려 하지 않다"],["融会贯通","róng huì guàn tōng","두루 꿰뚫어 이해하다"]],[["钦天监","Qīntiānjiān","흠천감(천문 관청)"],["天象","tiānxiàng","천문 현상"]],[["折服","zhéfú","감탄해 탄복하다"],["无不","wúbù","~하지 않는 이가 없다"],["高超","gāochāo","뛰어나다"]]]},{"o":["由于推广了滴灌技术，这一地区的农业用水量比十年前减少了两倍。","据统计，近年来报考基础数学专业的本科生人数比十年前增加了一倍。","“士别三日，当刮目相待”出自三国时期吕蒙的故事，告诉人们要用发展的眼光看人。","这款手机采用了全新的散热设计，即使长时间运行大型游戏也不会明显发热。"],"a":0,"type":"배수 감소","why":"줄어드는 것은 “倍”로 말할 수 없다. 분수(三分之二 등)로 써야 한다.","fix":"由于推广了滴灌技术，这一地区的农业用水量比十年前减少了三分之二。","words":[["滴灌","dīguàn","점적 관개"],["报考","bàokǎo","응시하다"],["刮目相待","guā mù xiāng dài","눈을 비비고 다시 보다"],["吕蒙","Lǚ Méng","여몽(삼국 시대 장수)"],["散热","sànrè","열을 식히다"]],"tr":["점적 관개 기술을 보급한 덕분에 이 지역의 농업 용수량은 10년 전보다 3분의 2 줄었다.","통계에 따르면 최근 기초수학과에 지원하는 학부생 수가 10년 전보다 두 배로 늘었다.","'선비가 사흘을 떨어져 있으면 눈을 비비고 다시 봐야 한다'는 삼국 시대 여몽의 이야기에서 나왔으며, 사람을 발전하는 눈으로 보라고 알려 준다.","이 휴대폰은 완전히 새로운 방열 설계를 써서, 큰 게임을 오래 돌려도 눈에 띄게 뜨거워지지 않는다."],"ow":[[["滴灌","dīguàn","점적 관개"],["推广","tuīguǎng","널리 보급하다"],["用水量","yòngshuǐliàng","물 사용량"]],[["报考","bàokǎo","응시하다"],["本科生","běnkēshēng","학부생"],["据统计","jù tǒngjì","통계에 따르면"]],[["刮目相待","guā mù xiāng dài","눈을 비비고 다시 보다"],["吕蒙","Lǚ Méng","여몽(삼국 시대 장수)"]],[["散热","sànrè","열을 식히다"],["采用","cǎiyòng","채택하다"],["发热","fārè","열이 나다"]]]},{"o":["老子在《道德经》中把“慈”“俭”“不敢为天下先”称为自己珍视的“三宝”。","研究人员发现，长期处于噪声环境中的人，罹患高血压的风险明显偏高。","南朝的祖冲之将圆周率精确到小数点后第七位，这一纪录保持了近千年。","新工艺投产后，这种芯片的生产成本降低了一倍，而良品率却提高了近两成。"],"a":3,"type":"배수 감소","why":"“降低了一倍”는 0이 된다는 말이라 틀렸다. 줄어든 것은 “一半”처럼 분수로 써야 한다.","fix":"新工艺投产后，这种芯片的生产成本降低了一半，而良品率却提高了近两成。","words":[["珍视","zhēnshì","소중히 여기다"],["罹患","líhuàn","(병에) 걸리다"],["祖冲之","Zǔ Chōngzhī","조충지(남조 수학자)"],["圆周率","yuánzhōulǜ","원주율"],["投产","tóuchǎn","생산에 들어가다"],["芯片","xīnpiàn","반도체 칩"],["良品率","liángpǐnlǜ","양품률"]],"tr":["노자는 《도덕경》에서 '자애', '검소', '감히 천하에 앞서지 않음'을 자신이 소중히 여기는 '세 가지 보물'이라고 했다.","연구자들은 오랫동안 소음 속에 지내는 사람이 고혈압에 걸릴 위험이 뚜렷하게 높다는 사실을 발견했다.","남조의 조충지는 원주율을 소수점 아래 일곱째 자리까지 정확히 구했고, 이 기록은 천 년 가까이 깨지지 않았다.","새 공정으로 생산을 시작한 뒤 이 반도체 칩의 생산 원가는 절반으로 줄고, 양품률은 20% 가까이 올랐다."],"ow":[[["珍视","zhēnshì","소중히 여기다"],["道德经","Dàodé Jīng","도덕경"],["三宝","sānbǎo","세 가지 보물"]],[["罹患","líhuàn","(병에) 걸리다"],["噪声","zàoshēng","소음"],["高血压","gāoxuèyā","고혈압"]],[["祖冲之","Zǔ Chōngzhī","조충지(남조 수학자)"],["圆周率","yuánzhōulǜ","원주율"]],[["投产","tóuchǎn","생산에 들어가다"],["芯片","xīnpiàn","반도체 칩"],["良品率","liángpǐnlǜ","양품률"]]]},{"o":["藏羚羊是青藏高原特有的珍稀动物，主要生活在海拔四千米以上的高寒草原。","这档文化节目邀请知名学者，系统讲解了《论语》《孟子》《道德经》以及先秦诸子典籍中的名言警句。","这项调查覆盖了全国三十多个城市，共收回有效问卷一万两千余份。","“学而不思则罔，思而不学则殆”强调了学习与思考相结合的重要性。"],"a":1,"type":"범위·분류","why":"《论语》《孟子》《道德经》은 모두 선진 제자 서적에 속하는데 “以及”로 따로 나란히 놓았다.","fix":"这档文化节目邀请知名学者，系统讲解了《论语》《孟子》《道德经》等先秦诸子典籍中的名言警句。","words":[["藏羚羊","zànglíngyáng","티베트영양"],["高寒","gāohán","높고 추운"],["名言警句","míngyán jǐngjù","명언과 경구"],["问卷","wènjuàn","설문지"],["学而不思则罔","xué ér bù sī zé wǎng","배우되 생각하지 않으면 어둡다"],["殆","dài","위태롭다"]],"tr":["티베트영양은 칭짱고원에만 사는 희귀 동물로, 주로 해발 4천 미터 이상의 춥고 높은 초원에 산다.","이 문화 프로그램은 유명 학자를 초청해 《논어》《맹자》《도덕경》 같은 선진 제자 서적의 명언과 경구를 체계적으로 풀어 주었다.","이 조사는 전국 30여 개 도시를 대상으로 했으며, 유효 설문지를 모두 1만 2천여 부 거두었다.","'배우되 생각하지 않으면 어둡고, 생각하되 배우지 않으면 위태롭다'는 말은 배움과 생각을 함께하는 것이 중요하다고 강조한다."],"ow":[[["藏羚羊","zànglíngyáng","티베트영양"],["高寒","gāohán","높고 추운"]],[["名言警句","míngyán jǐngjù","명언과 경구"],["先秦","Xiān Qín","선진"],["诸子","zhūzǐ","제자(여러 사상가)"],["典籍","diǎnjí","고전 서적"]],[["问卷","wènjuàn","설문지"],["覆盖","fùgài","포괄하다"],["有效","yǒuxiào","유효하다"]],[["学而不思则罔","xué ér bù sī zé wǎng","배우되 생각하지 않으면 어둡다"],["殆","dài","위태롭다"]]]},{"o":["“桃李不言，下自成蹊”出自《史记》，比喻为人真诚，自然会受到人们的敬重。","由于月球表面没有大气层的保护，昼夜温差接近三百摄氏度。","这位收藏家将多年收藏的书画、瓷器、玉器和艺术品共两千余件全部无偿捐给了国家。","这家小餐馆的老板坚持每天清晨去市场挑选最新鲜的食材，生意一直很红火。"],"a":2,"type":"범위·분류","why":"서화·도자기·옥기는 모두 “艺术品”에 속하는데 같은 층위로 나란히 놓았다.","fix":"这位收藏家将多年收藏的书画、瓷器、玉器等艺术品共两千余件全部无偿捐给了国家。","words":[["桃李不言，下自成蹊","táo lǐ bù yán, xià zì chéng xī","덕이 있으면 사람이 절로 모인다"],["敬重","jìngzhòng","존경하다"],["大气层","dàqìcéng","대기층"],["收藏家","shōucángjiā","수집가"],["玉器","yùqì","옥 공예품"],["无偿","wúcháng","무상으로"],["红火","hónghuo","번창하다"]],"tr":["'복숭아와 오얏은 말이 없어도 그 아래 절로 길이 난다'는 《사기》에서 나온 말로, 사람됨이 진실하면 저절로 존경을 받는다는 비유다.","달 표면은 대기층의 보호가 없어 낮과 밤의 기온 차가 300도에 가깝다.","이 수집가는 여러 해 모은 서화, 도자기, 옥 공예품 등 예술품 2천여 점을 모두 국가에 무상으로 기증했다.","이 작은 식당 주인은 날마다 이른 아침 시장에 가서 가장 신선한 재료를 골라 오는데, 장사가 늘 잘된다."],"ow":[[["桃李不言，下自成蹊","táo lǐ bù yán, xià zì chéng xī","덕이 있으면 사람이 절로 모인다"],["敬重","jìngzhòng","존경하다"]],[["大气层","dàqìcéng","대기층"],["月球","yuèqiú","달"],["摄氏度","shèshìdù","섭씨 도"]],[["收藏家","shōucángjiā","수집가"],["玉器","yùqì","옥 공예품"],["无偿","wúcháng","무상으로"]],[["红火","hónghuo","번창하다"],["食材","shícái","식재료"],["清晨","qīngchén","이른 아침"]]]},{"o":["考古学家们断定，这座墓葬大概是西汉某位诸侯王的陵墓。","孔子认为“过犹不及”，做事超过了限度，就和没有达到一样，都是不恰当的。","这种候鸟每年春天从南方飞来繁殖，秋天再带着幼鸟返回越冬地。","尽管已经退休多年，这位老教授仍笔耕不辍，每年都有新的研究成果问世。"],"a":0,"type":"자기모순","why":"“断定”(확실히 단정하다)와 “大概”(아마)가 서로 맞지 않는다.","fix":"考古学家们推测，这座墓葬大概是西汉某位诸侯王的陵墓。","words":[["断定","duàndìng","단정하다"],["墓葬","mùzàng","무덤"],["诸侯王","zhūhóuwáng","제후왕"],["陵墓","língmù","능묘"],["过犹不及","guò yóu bù jí","과유불급"],["繁殖","fánzhí","번식하다"],["笔耕不辍","bǐ gēng bú chuò","쉬지 않고 글을 쓰다"],["问世","wènshì","세상에 나오다"]],"tr":["고고학자들은 이 무덤이 서한의 어느 제후왕의 능일 것이라고 단정했다.","공자는 '지나침은 모자람과 같다'고 보았다. 일이 한도를 넘으면 미치지 못한 것과 마찬가지로 알맞지 않다는 뜻이다.","이 철새는 해마다 봄이면 남쪽에서 날아와 번식하고, 가을이면 새끼를 데리고 겨울을 나는 곳으로 돌아간다.","은퇴한 지 여러 해가 지났지만 이 노교수는 여전히 쉬지 않고 글을 써 해마다 새 연구 성과를 내놓는다."],"ow":[[["断定","duàndìng","단정하다"],["墓葬","mùzàng","무덤"],["诸侯王","zhūhóuwáng","제후왕"],["陵墓","língmù","능묘"]],[["过犹不及","guò yóu bù jí","과유불급"],["限度","xiàndù","한도"],["恰当","qiàdàng","알맞다"]],[["繁殖","fánzhí","번식하다"],["候鸟","hòuniǎo","철새"],["越冬地","yuèdōngdì","월동지"]],[["笔耕不辍","bǐ gēng bú chuò","쉬지 않고 글을 쓰다"],["问世","wènshì","세상에 나오다"]]]},{"o":["这片红树林不仅能防风消浪，还为许多鱼类和鸟类提供了理想的栖身之所。","《道德经》全书仅五千余字，却几乎涵盖了宇宙、人生、政治等方方面面，无一遗漏。","这项技术目前尚处于实验阶段，距离大规模商业化应用还有很长的路要走。","唐代诗人李白一生好游历，足迹遍及大半个中国，留下了许多描写名山大川的诗篇。"],"a":1,"type":"자기모순","why":"“几乎”(거의)라고 해 놓고 “无一遗漏”(하나도 빠짐없이)라고 해 앞뒤가 맞지 않는다.","fix":"《道德经》全书仅五千余字，却几乎涵盖了宇宙、人生、政治等方方面面。","words":[["红树林","hóngshùlín","맹그로브 숲"],["栖身","qīshēn","몸을 붙여 살다"],["涵盖","hángài","포괄하다"],["遗漏","yílòu","빠뜨리다"],["商业化","shāngyèhuà","상업화"],["好","hào","좋아하다"],["游历","yóulì","두루 돌아다니다"],["名山大川","míng shān dà chuān","이름난 산과 큰 강"]],"tr":["이 맹그로브 숲은 바람과 파도를 막아 줄 뿐 아니라 많은 물고기와 새에게 좋은 보금자리가 된다.","《도덕경》은 5천여 자에 불과하지만 우주, 인생, 정치 등 거의 모든 면을 다룬다.","이 기술은 아직 실험 단계에 있어 대규모 상업화까지는 갈 길이 멀다.","당나라 시인 이백은 평생 유람을 좋아해 중국 땅 절반 넘게 발자취를 남겼고, 이름난 산과 강을 노래한 시를 많이 남겼다."],"ow":[[["红树林","hóngshùlín","맹그로브 숲"],["栖身","qīshēn","몸을 붙여 살다"]],[["涵盖","hángài","포괄하다"],["遗漏","yílòu","빠뜨리다"]],[["商业化","shāngyèhuà","상업화"],["尚","shàng","아직"],["大规模","dàguīmó","대규모"]],[["好","hào","좋아하다"],["游历","yóulì","두루 돌아다니다"],["名山大川","míng shān dà chuān","이름난 산과 큰 강"]]]},{"o":["相传老子曾在周王室担任守藏室之史，这一职务大致相当于今天的国家图书馆馆长。","研究表明，适量摄入粗粮中的膳食纤维，有助于维持肠道菌群的平衡、降低某些慢性病的发病风险。","这座城市以“千年古都”的厚重底蕴吸引着八方来客，旅游业已成为其支柱产业。","这次调查共记录古树名木一百二十棵，其中树龄在五百年以上的有八十棵，三百年至五百年的有五十棵。"],"a":3,"type":"자기모순","why":"전체가 120그루인데 나눈 숫자 80과 50을 더하면 130그루라 앞뒤 숫자가 맞지 않는다.","fix":"这次调查共记录古树名木一百二十棵，其中树龄在五百年以上的有八十棵，三百年至五百年的有四十棵。","words":[["守藏室","shǒucángshì","주나라 왕실 서고"],["膳食纤维","shànshí xiānwéi","식이 섬유"],["菌群","jūnqún","균총"],["底蕴","dǐyùn","깊은 내공, 바탕"],["支柱产业","zhīzhù chǎnyè","기간 산업"],["古树名木","gǔshù míngmù","오래되고 이름난 나무"],["树龄","shùlíng","나무 나이"]],"tr":["노자는 주나라 왕실에서 수장실의 사관을 지냈다고 전해지는데, 이 직책은 오늘날 국립도서관장쯤에 해당한다.","연구에 따르면 잡곡 속 식이 섬유를 적당히 먹으면 장내 균형을 지키고 일부 만성병에 걸릴 위험을 낮추는 데 도움이 된다.","이 도시는 '천년 고도'의 깊은 역사로 각지의 손님을 끌어들이며, 관광업이 이미 기간 산업이 되었다.","이번 조사에서 오래되고 이름난 나무 120그루를 기록했는데, 그중 나이가 500년 넘은 나무가 80그루, 300~500년인 나무가 50그루였다."],"ow":[[["守藏室","shǒucángshì","주나라 왕실 서고"],["相传","xiāngchuán","전하는 말에 따르면"],["职务","zhíwù","직무"]],[["膳食纤维","shànshí xiānwéi","식이 섬유"],["菌群","jūnqún","균총"]],[["底蕴","dǐyùn","깊은 내공, 바탕"],["支柱产业","zhīzhù chǎnyè","기간 산업"]],[["古树名木","gǔshù míngmù","오래되고 이름난 나무"],["树龄","shùlíng","나무 나이"]]]}],[{"o":["这一带古建筑损毁严重，主要原因是长期缺乏维护以及近代多次战乱造成的。","孟子提出“富贵不能淫，贫贱不能移，威武不能屈”，为“大丈夫”确立了人格标准。","这部作品之所以能打动千万读者，是因为作者把自己的真实经历融入了字里行间。","传说中的“洛书”其实是一个三阶幻方，其横、竖、斜各行数字之和都等于十五。"],"a":0,"type":"구식 혼합","why":"“原因是…”와 “是…造成的” 두 문형을 섞었다. 하나만 써야 한다.","fix":"这一带古建筑损毁严重，主要是长期缺乏维护以及近代多次战乱造成的。","words":[["损毁","sǔnhuǐ","파손되다"],["战乱","zhànluàn","전란"],["富贵不能淫","fù guì bù néng yín","부귀도 마음을 흐트러뜨리지 못한다"],["威武不能屈","wēi wǔ bù néng qū","위세도 굴복시키지 못한다"],["字里行间","zì lǐ háng jiān","글의 행간"],["洛书","Luòshū","낙서(전설의 수 배열 그림)"],["幻方","huànfāng","마방진"]],"tr":["이 일대의 옛 건축물이 심하게 망가진 것은 주로 오랫동안 관리하지 않은 데다 근대에 여러 번 전란을 겪었기 때문이다.","맹자는 '부귀도 마음을 흐트러뜨리지 못하고, 가난도 뜻을 바꾸지 못하며, 위세도 굴복시키지 못한다'고 하여 '대장부'의 인격 기준을 세웠다.","이 작품이 수많은 독자를 감동시킨 까닭은 작가가 자신의 실제 경험을 글 곳곳에 녹여 냈기 때문이다.","전설 속 '낙서'는 사실 3차 마방진으로, 가로·세로·대각선 숫자를 더하면 모두 15가 된다."],"ow":[[["损毁","sǔnhuǐ","파손되다"],["战乱","zhànluàn","전란"]],[["富贵不能淫","fù guì bù néng yín","부귀도 마음을 흐트러뜨리지 못한다"],["威武不能屈","wēi wǔ bù néng qū","위세도 굴복시키지 못한다"]],[["字里行间","zì lǐ háng jiān","글의 행간"],["之所以","zhīsuǒyǐ","~한 까닭은"],["融入","róngrù","녹아들다"]],[["洛书","Luòshū","낙서(전설의 수 배열 그림)"],["幻方","huànfāng","마방진"]]]},{"o":["医生指出，只要及早发现、对症下药，这类慢性疾病大多是可以得到有效控制的。","庄子笔下“庄周梦蝶”的故事，探讨了梦境与现实、自我与外物之间的界限。","春秋战国时期的诸侯国之间，主要靠结盟与联姻为主来维持彼此间脆弱的力量平衡。","这座古镇依水而建，白墙黛瓦倒映在河中，宛如一幅意境悠远的水墨画。"],"a":2,"type":"구식 혼합","why":"“靠…来维持”와 “以…为主” 두 문형을 섞어 “靠…为主”가 됐다.","fix":"春秋战国时期的诸侯国之间，主要靠结盟与联姻来维持彼此间脆弱的力量平衡。","words":[["对症下药","duì zhèng xià yào","증상에 맞게 처방하다"],["梦境","mèngjìng","꿈속"],["结盟","jiéméng","동맹을 맺다"],["联姻","liányīn","혼인으로 맺어지다"],["脆弱","cuìruò","취약하다"],["黛瓦","dàiwǎ","검푸른 기와"],["倒映","dàoyìng","거꾸로 비치다"],["宛如","wǎnrú","마치 ~같다"]],"tr":["의사는 일찍 발견해 증상에 맞게 치료하면 이런 만성 질환은 대부분 효과적으로 다스릴 수 있다고 말했다.","장자가 쓴 '장주가 나비 꿈을 꾸다' 이야기는 꿈과 현실, 나와 바깥 사물 사이의 경계를 탐구한다.","춘추전국 시대 제후국들은 주로 동맹과 혼인으로 서로 간의 위태로운 힘의 균형을 유지했다.","이 옛 마을은 물가를 따라 지어져, 흰 벽과 검푸른 기와가 강물에 비친 모습이 마치 정취 깊은 수묵화 같다."],"ow":[[["对症下药","duì zhèng xià yào","증상에 맞게 처방하다"],["及早","jízǎo","일찍"],["慢性","mànxìng","만성"]],[["梦境","mèngjìng","꿈속"],["庄周梦蝶","Zhuāng Zhōu mèng dié","장주가 나비 꿈을 꾸다"],["界限","jièxiàn","경계"]],[["结盟","jiéméng","동맹을 맺다"],["联姻","liányīn","혼인으로 맺어지다"],["脆弱","cuìruò","취약하다"]],[["黛瓦","dàiwǎ","검푸른 기와"],["倒映","dàoyìng","거꾸로 비치다"],["宛如","wǎnrú","마치 ~같다"]]]},{"o":["孔子称赞颜回“一箪食，一瓢饮，在陋巷，人不堪其忧，回也不改其乐”。","随着保护力度的加大，长江江豚的种群数量近年来出现了止跌回升的迹象。","这位民间艺人用一块普通的面团，捏出了栩栩如生的十二生肖形象。","一个企业能否在危机中转危为安，关键在于领导者的决断力起着决定性的作用。"],"a":3,"type":"구식 혼합","why":"“关键在于…”와 “…起着决定性的作用” 두 문형을 섞었다.","fix":"一个企业能否在危机中转危为安，关键在于领导者的决断力。","words":[["箪","dān","대나무 밥그릇"],["瓢","piáo","표주박"],["陋巷","lòuxiàng","누추한 골목"],["江豚","jiāngtún","상괭이"],["止跌回升","zhǐ diē huí shēng","하락을 멈추고 반등하다"],["栩栩如生","xǔ xǔ rú shēng","살아 있는 듯 생생하다"],["转危为安","zhuǎn wēi wéi ān","위기를 넘겨 안정되다"],["决断力","juéduànlì","결단력"]],"tr":["공자는 안회를 두고 '대그릇 밥 한 그릇, 표주박 물 한 바가지로 누추한 골목에 사니 남들은 그 근심을 견디지 못하는데, 안회는 그 즐거움을 바꾸지 않는다'고 칭찬했다.","보호가 강화되면서 창장강 상괭이 개체 수가 최근 들어 줄어들다가 다시 늘어나는 조짐을 보이고 있다.","이 민간 예술가는 평범한 밀가루 반죽 한 덩이로 살아 있는 듯한 열두 띠 동물을 빚어냈다.","기업이 위기를 넘겨 안정을 찾을 수 있느냐는 지도자의 결단력에 달려 있다."],"ow":[[["箪","dān","대나무 밥그릇"],["瓢","piáo","표주박"],["陋巷","lòuxiàng","누추한 골목"]],[["江豚","jiāngtún","상괭이"],["止跌回升","zhǐ diē huí shēng","하락을 멈추고 반등하다"]],[["栩栩如生","xǔ xǔ rú shēng","살아 있는 듯 생생하다"],["面团","miàntuán","밀가루 반죽"],["生肖","shēngxiào","띠"]],[["转危为安","zhuǎn wēi wéi ān","위기를 넘겨 안정되다"],["决断力","juéduànlì","결단력"]]]},{"o":["墨子带领弟子日夜兼程赶到楚国，凭借过人的智慧说服楚王放弃了攻打宋国的计划。","这片湿地面积的急剧萎缩，是多年来过度围垦和上游截流的结果所致。","研究显示，每天保持适量的户外活动，能有效降低青少年近视的发生率。","这家出版社推出的古籍整理丛书，校勘精审，注释详明，深受学界好评。"],"a":1,"type":"구식 혼합","why":"“是…的结果”와 “是…所致” 두 문형을 섞었다. 하나만 써야 한다.","fix":"这片湿地面积的急剧萎缩，是多年来过度围垦和上游截流的结果。","words":[["日夜兼程","rì yè jiān chéng","밤낮없이 길을 재촉하다"],["萎缩","wěisuō","줄어들다"],["围垦","wéikěn","간척하다"],["截流","jiéliú","물길을 막다"],["所致","suǒzhì","~로 인한 것이다"],["近视","jìnshì","근시"],["丛书","cóngshū","총서"],["校勘","jiàokān","교감하다(원문 대조)"]],"tr":["묵자는 제자들을 이끌고 밤낮없이 초나라로 달려가, 뛰어난 지혜로 초왕을 설득해 송나라를 치려던 계획을 포기하게 했다.","이 습지의 면적이 급격히 줄어든 것은 여러 해 동안 지나치게 간척하고 상류에서 물길을 막은 결과다.","연구에 따르면 날마다 적당히 야외 활동을 하면 청소년 근시 발생률을 효과적으로 낮출 수 있다.","이 출판사가 낸 고서 정리 총서는 교감이 꼼꼼하고 주석이 자세해 학계의 호평을 받는다."],"ow":[[["日夜兼程","rì yè jiān chéng","밤낮없이 길을 재촉하다"],["凭借","píngjiè","~에 기대어"],["说服","shuōfú","설득하다"]],[["萎缩","wěisuō","줄어들다"],["围垦","wéikěn","간척하다"],["截流","jiéliú","물길을 막다"],["所致","suǒzhì","~로 인한 것이다"]],[["近视","jìnshì","근시"],["户外","hùwài","야외"],["发生率","fāshēnglǜ","발생률"]],[["丛书","cóngshū","총서"],["校勘","jiàokān","교감하다(원문 대조)"]]]},{"o":["他出身于书香门第，自幼饱读诗书，十八岁便考中了举人。","这项医保政策实施以来，城乡居民看病就医的经济负担有了明显减轻。","从“曾参杀人”的故事中，使我们懂得了流言一再重复，便足以动摇最坚定的信任。","位于云南西双版纳的热带雨林，是我国生物多样性最为丰富的地区之一。"],"a":2,"type":"주어 결여","why":"“从…中，使…” 때문에 주어가 없다. “使”를 빼야 “我们”이 주어가 된다.","fix":"从“曾参杀人”的故事中，我们懂得了流言一再重复，便足以动摇最坚定的信任。","words":[["书香门第","shū xiāng mén dì","대대로 글 읽는 집안"],["饱读诗书","bǎo dú shī shū","책을 많이 읽다"],["举人","jǔrén","거인(향시 합격자)"],["曾参","Zēng Shēn","증삼(공자 제자)"],["流言","liúyán","뜬소문"],["动摇","dòngyáo","흔들다"],["西双版纳","Xīshuāngbǎnnà","시솽반나"],["生物多样性","shēngwù duōyàngxìng","생물 다양성"]],"tr":["그는 대대로 글 읽는 집안에서 태어나 어려서부터 책을 많이 읽었고, 열여덟 살에 거인에 합격했다.","이 의료보험 정책이 시행된 뒤 도시와 농촌 주민이 병원에 다니는 경제적 부담이 눈에 띄게 줄었다.","'증삼이 사람을 죽였다' 이야기에서 우리는 뜬소문도 거듭되면 가장 굳은 믿음마저 흔들 수 있다는 것을 배운다.","윈난성 시솽반나의 열대우림은 중국에서 생물 다양성이 가장 풍부한 지역 가운데 하나다."],"ow":[[["书香门第","shū xiāng mén dì","대대로 글 읽는 집안"],["饱读诗书","bǎo dú shī shū","책을 많이 읽다"],["举人","jǔrén","거인(향시 합격자)"]],[["医保","yībǎo","의료보험"],["负担","fùdān","부담"]],[["曾参","Zēng Shēn","증삼(공자 제자)"],["流言","liúyán","뜬소문"],["动摇","dòngyáo","흔들다"]],[["西双版纳","Xīshuāngbǎnnà","시솽반나"],["生物多样性","shēngwù duōyàngxìng","생물 다양성"]]]},{"o":["这位县令到任后兴修水利、劝课农桑，大大增进了当地百姓的生活水平。","古代的计里鼓车每行一里便自动击鼓一次，是一种利用齿轮传动的计程装置。","古人常以人体部位作为长度标准，“布手知尺，布指知寸”说的正是这种做法。","科研人员在这片深海海域首次观察到一种能够发出微弱荧光的小型鲨鱼。"],"a":0,"type":"동사–목적어","why":"“增进”은 우정·이해 같은 말과 어울리고 “水平”(수준)과는 맞지 않는다. 수준은 “提高”한다.","fix":"这位县令到任后兴修水利、劝课农桑，大大提高了当地百姓的生活水平。","words":[["县令","xiànlìng","현령"],["兴修水利","xīngxiū shuǐlì","수리 시설을 만들다"],["劝课农桑","quàn kè nóng sāng","농업과 양잠을 권장하다"],["增进","zēngjìn","증진하다"],["计里鼓车","jìlǐ gǔchē","기리고거(거리 재는 수레)"],["齿轮","chǐlún","톱니바퀴"],["布手知尺","bù shǒu zhī chǐ","손을 펴서 한 자를 안다"],["荧光","yíngguāng","형광"]],"tr":["이 현령은 부임한 뒤 수리 시설을 만들고 농사와 양잠을 권장해 그 지역 백성의 생활 수준을 크게 끌어올렸다.","옛 기리고거는 1리를 갈 때마다 저절로 북을 한 번 치는 수레로, 톱니바퀴의 맞물림을 이용한 거리 측정 장치다.","옛사람들은 흔히 몸의 부위를 길이 기준으로 삼았는데, '손을 펴서 한 자를 알고 손가락을 펴서 한 치를 안다'는 말이 바로 이 방법을 가리킨다.","연구진은 이 심해에서 희미한 형광을 낼 수 있는 작은 상어를 처음으로 관찰했다."],"ow":[[["县令","xiànlìng","현령"],["兴修水利","xīngxiū shuǐlì","수리 시설을 만들다"],["劝课农桑","quàn kè nóng sāng","농업과 양잠을 권장하다"],["增进","zēngjìn","증진하다"]],[["计里鼓车","jìlǐ gǔchē","기리고거(거리 재는 수레)"],["齿轮","chǐlún","톱니바퀴"]],[["布手知尺","bù shǒu zhī chǐ","손을 펴서 한 자를 안다"],["部位","bùwèi","부위"],["布指知寸","bù zhǐ zhī cùn","손가락을 펴서 한 치를 안다"]],[["荧光","yíngguāng","형광"],["海域","hǎiyù","해역"],["微弱","wēiruò","희미하다"]]]},{"o":["这项历时五年的大型考古项目，揭示了良渚古城完整的水利系统和城市布局。","“上有天堂，下有苏杭”这句俗语，道出了苏州和杭州的富庶与秀美。","人体内的水分一旦流失过多，就可能出现头晕、乏力甚至休克等症状。","即使屡遭贬谪、身处逆境，刘禹锡却始终保持着豁达乐观的心态，写下了“沉舟侧畔千帆过”的名句。"],"a":3,"type":"짝 오류","why":"“即使”는 가정이라 “也”와 짝인데, 실제 있었던 일을 말하며 “却”와 이었다. “尽管…却”로 써야 한다.","fix":"尽管屡遭贬谪、身处逆境，刘禹锡却始终保持着豁达乐观的心态，写下了“沉舟侧畔千帆过”的名句。","words":[["良渚","Liángzhǔ","량주(신석기 유적)"],["富庶","fùshù","풍요롭다"],["乏力","fálì","기운이 없다"],["休克","xiūkè","쇼크"],["贬谪","biǎnzhé","좌천되다"],["逆境","nìjìng","역경"],["刘禹锡","Liú Yǔxī","유우석(당 시인)"],["豁达","huòdá","너그럽고 활달하다"]],"tr":["5년에 걸친 이 대형 고고학 사업은 량주 옛 도시의 온전한 수리 체계와 도시 구조를 밝혀냈다.","'위에는 천당이 있고 아래에는 쑤저우와 항저우가 있다'는 속담은 두 도시의 풍요로움과 아름다움을 잘 드러낸다.","몸속 수분이 한번 너무 많이 빠져나가면 어지러움, 무기력, 심하면 쇼크 같은 증상이 나타날 수 있다.","여러 번 좌천되어 역경에 처했어도 유우석은 늘 너그럽고 낙천적인 마음을 지켜 '가라앉은 배 곁으로 천 척의 배가 지나간다'는 명구를 남겼다."],"ow":[[["良渚","Liángzhǔ","량주(신석기 유적)"],["揭示","jiēshì","밝혀내다"],["布局","bùjú","구조, 배치"]],[["富庶","fùshù","풍요롭다"],["俗语","súyǔ","속담"],["秀美","xiùměi","수려하다"]],[["乏力","fálì","기운이 없다"],["休克","xiūkè","쇼크"]],[["贬谪","biǎnzhé","좌천되다"],["逆境","nìjìng","역경"],["刘禹锡","Liú Yǔxī","유우석(당 시인)"],["豁达","huòdá","너그럽고 활달하다"]]]},{"o":["清代宫廷制作的手摇计算机至今仍收藏在故宫博物院，见证了中西科技交流的历史。","不少学者否认《黄帝内经》不是一时一人之作，认为它是历代医家不断增补而成的。","孔子提出“君子喻于义，小人喻于利”，把对待义与利的态度作为区分君子与小人的标准。","这家工厂引进智能生产线后，生产效率大幅提升，产品次品率也随之下降。"],"a":1,"type":"이중 부정","why":"“否认”과 “不是”가 겹쳐 ‘한 사람의 작품이다’라는 뜻이 되어 뒤 내용(여러 의사가 보탰다)과 부딪친다.","fix":"不少学者认为《黄帝内经》不是一时一人之作，而是历代医家不断增补而成的。","words":[["手摇计算机","shǒuyáo jìsuànjī","손으로 돌리는 계산기"],["见证","jiànzhèng","증명하다, 지켜보다"],["黄帝内经","Huángdì Nèijīng","황제내경"],["增补","zēngbǔ","보충하다"],["喻于义","yùyúyì","의리에 밝다"],["次品率","cìpǐnlǜ","불량률"],["生产线","shēngchǎnxiàn","생산 라인"]],"tr":["빙하는 지구에서 가장 큰 담수 저장고로, 전 세계 담수의 약 70%를 품고 있다.","많은 학자는 《황제내경》이 한 시대 한 사람의 작품이 아니며, 역대 의사들이 계속 보태어 이루어진 책이라고 본다.","공자는 '군자는 의리에 밝고 소인은 이익에 밝다'고 하여, 의리와 이익을 대하는 태도를 군자와 소인을 가르는 기준으로 삼았다.","이 공장은 스마트 생산 라인을 들여온 뒤 생산 효율이 크게 오르고 불량률도 그에 따라 떨어졌다."],"ow":[[["手摇计算机","shǒuyáo jìsuànjī","손으로 돌리는 계산기"],["见证","jiànzhèng","증명하다, 지켜보다"]],[["黄帝内经","Huángdì Nèijīng","황제내경"],["增补","zēngbǔ","보충하다"]],[["喻于义","yùyúyì","의리에 밝다"],["小人","xiǎorén","소인"],["区分","qūfēn","구분하다"]],[["次品率","cìpǐnlǜ","불량률"],["生产线","shēngchǎnxiàn","생산 라인"]]]},{"o":["截至目前为止，这一流域已累计建成生态护岸六百余公里，水质明显好转。","“知之为知之，不知为不知，是知也”，告诫我们治学要实事求是，不能不懂装懂。","这种蘑菇外表鲜艳诱人，却含有剧毒，误食后可能危及生命。","这位年轻的钢琴家在国际比赛中脱颖而出，被评委誉为“百年一遇的天才”。"],"a":0,"type":"뜻 중복","why":"“截至目前”과 “到目前为止”를 섞어 ‘지금까지’라는 뜻이 겹쳤다.","fix":"截至目前，这一流域已累计建成生态护岸六百余公里，水质明显好转。","words":[["截至","jiézhì","~까지"],["流域","liúyù","유역"],["累计","lěijì","누계하다"],["护岸","hù'àn","호안(강둑 보호 시설)"],["治学","zhìxué","학문을 하다"],["实事求是","shí shì qiú shì","사실에 근거해 진리를 찾다"],["剧毒","jùdú","맹독"],["脱颖而出","tuō yǐng ér chū","두각을 나타내다"]],"tr":["지금까지 이 유역에는 생태 호안이 누계 600여 km 만들어졌고 수질이 눈에 띄게 좋아졌다.","'아는 것을 안다 하고 모르는 것을 모른다 하는 것이 아는 것이다'라는 말은 학문을 할 때 사실대로 하고 모르면서 아는 척하지 말라고 일깨운다.","이 버섯은 겉모습이 화려하고 먹음직스럽지만 맹독이 있어 잘못 먹으면 목숨이 위험할 수 있다.","이 젊은 피아니스트는 국제 대회에서 두각을 나타내 심사위원들에게 '백 년에 한 번 나올 천재'라는 찬사를 받았다."],"ow":[[["截至","jiézhì","~까지"],["流域","liúyù","유역"],["累计","lěijì","누계하다"],["护岸","hù'àn","호안(강둑 보호 시설)"]],[["治学","zhìxué","학문을 하다"],["实事求是","shí shì qiú shì","사실에 근거해 진리를 찾다"]],[["剧毒","jùdú","맹독"],["鲜艳","xiānyàn","화려하다"],["误食","wùshí","잘못 먹다"],["危及","wēijí","위태롭게 하다"]],[["脱颖而出","tuō yǐng ér chū","두각을 나타내다"],["评委","píngwěi","심사위원"],["百年一遇","bǎi nián yí yù","백 년에 한 번"]]]},{"o":["端午节赛龙舟的习俗在我国南方地区尤为盛行，每年都吸引大批观众前来观看。","“不积跬步，无以至千里”出自《荀子·劝学》，强调了点滴积累对于成就大事的意义。","这部著作全面梳理了先秦至两汉时期儒家礼乐思想的发展脉络，填补了国内这一研究领域长期以来的。","适度的压力能激发人的潜能，但长期处于高压状态则会损害身心健康。"],"a":2,"type":"목적어 결여","why":"“填补了…长期以来的” 뒤에 무엇을 메웠는지 목적어(空白)가 없다.","fix":"这部著作全面梳理了先秦至两汉时期儒家礼乐思想的发展脉络，填补了国内这一研究领域长期以来的空白。","words":[["盛行","shèngxíng","성행하다"],["跬步","kuǐbù","반걸음"],["劝学","Quànxué","권학(순자 편명)"],["梳理","shūlǐ","정리하다"],["礼乐","lǐyuè","예악"],["脉络","màiluò","맥락"],["填补","tiánbǔ","메우다"],["潜能","qiánnéng","잠재력"]],"tr":["단오에 용선 경주를 하는 풍습은 중국 남부 지역에서 특히 성행하며, 해마다 많은 관중이 구경하러 온다.","'반걸음이라도 쌓지 않으면 천 리에 이를 수 없다'는 《순자·권학》에서 나온 말로, 작은 것을 꾸준히 쌓는 것이 큰일을 이루는 데 얼마나 중요한지 강조한다.","이 저서는 선진부터 양한까지 유가 예악 사상의 발전 맥락을 두루 정리해, 국내 이 연구 분야의 오랜 공백을 메웠다.","적당한 스트레스는 사람의 잠재력을 끌어내지만, 오랫동안 높은 압박 속에 있으면 몸과 마음의 건강을 해친다."],"ow":[[["盛行","shèngxíng","성행하다"],["赛龙舟","sài lóngzhōu","용선 경주"],["尤为","yóuwéi","특히"]],[["跬步","kuǐbù","반걸음"],["劝学","Quànxué","권학(순자 편명)"]],[["梳理","shūlǐ","정리하다"],["礼乐","lǐyuè","예악"],["脉络","màiluò","맥락"],["填补","tiánbǔ","메우다"]],[["潜能","qiánnéng","잠재력"],["激发","jīfā","불러일으키다"],["损害","sǔnhài","해치다"]]]}]];
